// data/sentences.js - 翻译练习句库（中英互译）
// lv 与词汇等级对应；w 为本句考查的核心词汇 id；note 为解析/考点句型
const SENTENCES = [
  // ---------- Lv1 入门 ----------
  { id: 1,  lv: 1, en: 'Practice is the key to improving your English.', zh: '练习是提高英语水平的关键。', w: [4, 1], note: 'the key to (doing) sth. 做某事的关键，to 为介词' },
  { id: 2,  lv: 1, en: 'Good habits are very important for success in any field.', zh: '好习惯对任何领域的成功都非常重要。', w: [2, 5, 11], note: 'be important for 对……重要' },
  { id: 3,  lv: 1, en: 'It is difficult to make progress without enough practice.', zh: '没有足够的练习就很难取得进步。', w: [6, 12, 4], note: 'It is + adj. + to do sth.；make progress 取得进步' },
  { id: 4,  lv: 1, en: 'A good education gives people more opportunities in life.', zh: '良好的教育会给人们带来更多人生机会。', w: [13, 14], note: '' },
  { id: 5,  lv: 1, en: 'We should protect the environment for our children and grandchildren.', zh: '我们应该为了子孙后代保护环境。', w: [7], note: '' },
  { id: 6,  lv: 1, en: 'Confidence is the first step on the road to success.', zh: '自信是通往成功之路的第一步。', w: [15, 11], note: 'the first step to ……的第一步' },
  { id: 7,  lv: 1, en: 'Different people have different abilities, so we should help each other.', zh: '不同的人有不同的能力，所以我们应该互相帮助。', w: [10, 9], note: '' },
  { id: 8,  lv: 1, en: 'Reading is a good way to gain knowledge.', zh: '阅读是获得知识的好方法。', w: [3], note: 'a way to do sth. 做某事的方法' },
  { id: 9,  lv: 1, en: 'Modern society needs people with both knowledge and practical skills.', zh: '现代社会需要既有知识又有实践能力的人。', w: [16, 3], note: '' },
  { id: 10, lv: 1, en: 'He has developed a good habit of getting up early.', zh: '他养成了早起的好习惯。', w: [8, 2], note: 'develop a habit of doing 养成做某事的习惯' },
  { id: 11, lv: 1, en: 'As the saying goes, practice makes perfect, so keep going.', zh: '俗话说熟能生巧，所以坚持下去吧。', w: [4], note: '英语谚语，注意汉译采用意译' },
  // ---------- Lv2 基础 ----------
  { id: 12, lv: 2, en: 'We should try our best to achieve our goals.', zh: '我们应该尽力实现自己的目标。', w: [17, 25], note: "try one's best to do 尽力做某事" },
  { id: 13, lv: 2, en: 'Efficient communication between teammates can reduce misunderstandings at work.', zh: '团队成员之间高效沟通可以减少工作中的误解。', w: [19, 21, 28], note: '' },
  { id: 14, lv: 2, en: 'Technology has greatly changed our way of life.', zh: '科技极大地改变了我们的生活方式。', w: [22], note: '现在完成时表示对现在的影响' },
  { id: 15, lv: 2, en: 'A positive attitude helps us face challenges with more courage.', zh: '积极的态度帮助我们更有勇气地面对挑战。', w: [24, 18], note: 'help sb. (to) do sth.' },
  { id: 16, lv: 2, en: 'Everyone should be responsible for his own behavior.', zh: '每个人都应该对自己的行为负责。', w: [20], note: 'be responsible for 对……负责' },
  { id: 17, lv: 2, en: 'The local government should increase investment in public education every year.', zh: '地方政府应该逐年增加对公共教育的投入。', w: [29, 13], note: '' },
  { id: 18, lv: 2, en: 'We must improve the quality of our products.', zh: '我们必须提高产品的质量。', w: [27, 1], note: '' },
  { id: 19, lv: 2, en: 'The economy of this area is developing rapidly.', zh: '这个地区的经济正在迅速发展。', w: [30, 8], note: '' },
  { id: 20, lv: 2, en: 'Culture has a deep influence on people\'s lives.', zh: '文化对人们的生活有着深刻的影响。', w: [31, 32], note: 'have an influence on 对……有影响' },
  { id: 21, lv: 2, en: 'We should make full use of these resources.', zh: '我们应该充分利用这些资源。', w: [23], note: 'make full use of 充分利用' },
  { id: 22, lv: 2, en: 'Hard work and constant effort usually lead to real success.', zh: '勤奋加持续的努力通常会带来真正的成功。', w: [26, 11], note: 'lead to 通向；导致' },
  // ---------- Lv3 进阶 ----------
  { id: 23, lv: 3, en: 'We should acquire useful knowledge through daily practice and reflection.', zh: '我们应该通过日常实践和反思来获取有用的知识。', w: [33, 3, 4], note: '' },
  { id: 24, lv: 3, en: 'This book gives a comprehensive introduction to English grammar.', zh: '这本书全面介绍了英语语法。', w: [34], note: 'give an introduction to 介绍……' },
  { id: 25, lv: 3, en: 'Exercise plays a significant role in keeping healthy.', zh: '锻炼对保持健康起着重要作用。', w: [35, 37], note: 'play a significant role in 在……中起重要作用' },
  { id: 26, lv: 3, en: 'Everyone can contribute to protecting the environment in small daily ways.', zh: '每个人都可以通过日常小事为保护环境出力。', w: [36, 7], note: 'contribute to doing sth.，to 为介词' },
  { id: 27, lv: 3, en: 'We should maintain a balance between work and rest.', zh: '我们应该保持工作与休息的平衡。', w: [37], note: 'maintain a balance between A and B' },
  { id: 28, lv: 3, en: 'From my perspective, learning English requires long-term motivation.', zh: '在我看来，学习英语需要持久的动力。', w: [39, 47], note: "from one's perspective 在某人看来" },
  { id: 29, lv: 3, en: 'We need to adapt to the changing society.', zh: '我们需要适应不断变化的社会。', w: [41, 16], note: 'adapt to 适应' },
  { id: 30, lv: 3, en: 'Innovation has become the driving force of economic and social development.', zh: '创新已成为经济与社会发展的驱动力。', w: [42, 8], note: '' },
  { id: 31, lv: 3, en: 'It is critical to develop a good learning strategy.', zh: '制定良好的学习策略至关重要。', w: [44, 40, 8], note: 'It is critical to do sth. 做某事至关重要' },
  { id: 32, lv: 3, en: 'This social phenomenon has attracted wide attention from the public.', zh: '这一社会现象已引起公众的广泛关注。', w: [45], note: 'attract attention 引起关注' },
  { id: 33, lv: 3, en: 'Academic success depends on both effort and methods.', zh: '学业上的成功取决于努力和方法。', w: [46, 26, 11], note: 'depend on 取决于；both...and...' },
  { id: 34, lv: 3, en: 'Every individual has the potential to succeed if they keep trying.', zh: '只要坚持尝试，每个人都有成功的潜力。', w: [38, 48], note: 'have the potential to do 有做某事的潜力' },
  { id: 35, lv: 3, en: 'We should follow a sustainable path of development.', zh: '我们应该走可持续发展的道路。', w: [43, 8], note: '' },
  // ---------- Lv4 冲刺 ----------
  { id: 36, lv: 4, en: 'We should not underestimate the importance of English.', zh: '我们不应低估英语的重要性。', w: [54, 5], note: 'the importance of ……的重要性' },
  { id: 37, lv: 4, en: 'The government has taken measures to alleviate poverty.', zh: '政府已采取措施减轻贫困。', w: [49], note: 'take measures to do 采取措施做某事' },
  { id: 38, lv: 4, en: 'The Internet has brought unprecedented changes to our lives.', zh: '互联网给我们的生活带来了前所未有的变化。', w: [50], note: 'bring changes to 给……带来变化' },
  { id: 39, lv: 4, en: 'It is inevitable that technology will change our lives.', zh: '科技改变我们的生活是不可避免的。', w: [51, 22], note: 'It is inevitable that... ……是不可避免的' },
  { id: 40, lv: 4, en: 'We should consolidate what we have learned before moving on.', zh: '在进入下一步之前，我们应该巩固已学的内容。', w: [52], note: 'what 引导宾语从句' },
  { id: 41, lv: 4, en: 'Convenient public transportation can facilitate the economic development of a city.', zh: '便捷的公共交通可以促进一座城市的经济发展。', w: [53, 30, 8], note: '' },
  { id: 42, lv: 4, en: 'The city is famous for its prosperity and diversity.', zh: '这座城市以其繁荣和多样性而闻名。', w: [55, 60], note: 'be famous for 以……闻名' },
  { id: 43, lv: 4, en: 'The government should improve the infrastructure of the city.', zh: '政府应该改善城市的基础设施。', w: [56, 1], note: '' },
  { id: 44, lv: 4, en: 'We should take the initiative to learn new things.', zh: '我们应该主动学习新事物。', w: [57], note: 'take the initiative to do 主动做某事' },
  { id: 45, lv: 4, en: 'The reform has had a profound influence on society.', zh: '改革对社会产生了深远的影响。', w: [58, 32, 16], note: 'have a profound influence on 对……有深远影响' },
  { id: 46, lv: 4, en: 'We must accelerate the pace of reform to meet people\'s needs.', zh: '为了满足人们的需求，我们必须加快改革的步伐。', w: [59], note: 'the pace of ……的步伐' },
  { id: 47, lv: 4, en: 'The Internet has transformed the way we communicate.', zh: '互联网改变了我们交流的方式。', w: [61, 21], note: 'the way (that) we communicate，省略关系词的定语从句' },
  { id: 48, lv: 4, en: 'We should consider the consequences of our actions.', zh: '我们应该考虑自己行为的后果。', w: [62], note: '' },
  { id: 49, lv: 4, en: 'Education should always be given top priority in public spending.', zh: '在公共支出中，教育永远都应被放在最优先的位置。', w: [63, 13], note: '被动语态；top priority 最优先事项' },
  { id: 50, lv: 4, en: 'The country has made substantial progress in science.', zh: '这个国家在科学方面取得了巨大的进步。', w: [64, 12], note: 'make progress in 在……方面取得进步' },

  // ---------- Lv1 扩充（id 51 起，对应新增入门词） ----------
  { id: 51, lv: 1, en: 'We should accept helpful advice from people who care about us.', zh: '我们应该接受关心我们的人给出的有用建议。', w: [65, 66], note: '' },
  { id: 52, lv: 1, en: 'My teacher gave me some useful advice about learning new words.', zh: '老师给了我一些学习生词的有用建议。', w: [66], note: 'give sb. advice about 就……给某人建议' },
  { id: 53, lv: 1, en: 'Do not be afraid of making mistakes when you speak English.', zh: '说英语时不要害怕犯错。', w: [67], note: 'be afraid of doing 害怕做某事' },
  { id: 54, lv: 1, en: 'I agree with you that reading every day really helps a lot.', zh: '我同意你的看法：每天阅读确实很有帮助。', w: [68], note: 'agree with sb. 同意某人' },
  { id: 55, lv: 1, en: 'We need to leave for the airport two hours before the flight.', zh: '我们需要在航班起飞前两小时出发去机场。', w: [69], note: 'leave for 动身去' },
  { id: 56, lv: 1, en: 'My parents allow me to watch an English movie on weekends.', zh: '父母允许我周末看一部英文电影。', w: [70], note: 'allow sb. to do 允许某人做' },
  { id: 57, lv: 1, en: 'She likes to study alone in the library on Saturday mornings.', zh: '她喜欢周六上午一个人在图书馆学习。', w: [71], note: '' },
  { id: 58, lv: 1, en: 'I have already finished my homework, so I can go out now.', zh: '我已经写完作业了，现在可以出去。', w: [72], note: '现在完成时' },
  { id: 59, lv: 1, en: 'Although he is very busy, he still reads English every morning.', zh: '虽然他很忙，但仍然每天早上读英语。', w: [73], note: 'although 引导让步状语从句' },
  { id: 60, lv: 1, en: 'My English teacher always encourages us to ask more questions in class.', zh: '英语老师总是鼓励我们在课堂上多提问。', w: [74], note: 'encourage sb. to do 鼓励某人做' },
  { id: 61, lv: 1, en: 'Please do not get angry when you cannot remember a new word.', zh: '想不起新单词时请不要生气。', w: [75], note: 'get angry 生气' },
  { id: 62, lv: 1, en: 'The little boy wants to keep an animal as a pet at home.', zh: '小男孩想在家养一只动物当宠物。', w: [76], note: '' },
  { id: 63, lv: 1, en: 'Can you answer this question in English without any help?', zh: '你能不用任何帮助就用英语回答这个问题吗？', w: [77], note: '' },
  { id: 64, lv: 1, en: 'These new words often appear again in the next chapter of the book.', zh: '这些生词经常会在书的下一章再次出现。', w: [78], note: '' },
  { id: 65, lv: 1, en: 'They arrived at the small station just before it got dark.', zh: '天黑前他们刚好到达那个小车站。', w: [79], note: 'arrive at 到达（小地点）' },
  { id: 66, lv: 1, en: 'She is studying art at a college in the center of the city.', zh: '她正在市中心的一所学院学习艺术。', w: [80], note: '' },
  { id: 67, lv: 1, en: 'If you do not understand, you should ask your teacher for help.', zh: '如果你不明白，应该向老师求助。', w: [81], note: 'ask sb. for help 向某人求助' },
  { id: 68, lv: 1, en: 'Please pay attention to the way native speakers use these common words.', zh: '请注意母语者使用这些常见词的方式。', w: [82, 145], note: 'pay attention to 注意，to 为介词' },
  { id: 69, lv: 1, en: 'The weather in autumn here is cool and perfect for outdoor reading.', zh: '这里秋天的天气凉爽，非常适合户外阅读。', w: [83], note: '' },
  { id: 70, lv: 1, en: 'Try to avoid translating every word in your head while you read.', zh: '阅读时尽量避免在脑子里逐词翻译。', w: [84], note: 'avoid doing 避免做某事' },
  { id: 71, lv: 1, en: 'The baby next door smiles at everyone who walks past her.', zh: '隔壁的宝宝对每一个路过的人微笑。', w: [85], note: 'who 引导定语从句' },
  { id: 72, lv: 1, en: 'One bad habit can slow down your progress in learning English.', zh: '一个坏习惯就会拖慢你学英语的进度。', w: [86], note: 'slow down 拖慢' },
  { id: 73, lv: 1, en: 'There is a small bank across the street from my office.', zh: '我办公室对面有一家小银行。', w: [87], note: 'across the street 街对面' },
  { id: 74, lv: 1, en: 'You should learn the basic words before reading long English articles.', zh: '在阅读长篇英语文章之前，你应该先学会基础词汇。', w: [88], note: '' },
  { id: 75, lv: 1, en: 'We took a long walk along the beach after the rain stopped.', zh: '雨停后我们沿着海滩走了很久。', w: [89], note: '' },
  { id: 76, lv: 1, en: 'I cannot bear the noise outside when I am trying to study.', zh: '我想学习时无法忍受外面的噪音。', w: [90], note: 'bear = stand 忍受' },
  { id: 77, lv: 1, en: 'The campus looks especially beautiful when the trees turn yellow in autumn.', zh: '秋天树叶变黄时，校园显得格外美丽。', w: [91], note: '' },
  { id: 78, lv: 1, en: 'Reading every day has become a natural part of my morning routine.', zh: '每天阅读已经成为我早晨习惯中自然的一部分。', w: [92], note: 'become part of 成为……的一部分' },
  { id: 79, lv: 1, en: 'Let us begin with the easiest words and then move on slowly.', zh: '我们从最简单的单词开始，然后再慢慢推进。', w: [93], note: 'begin with 以……开始' },
  { id: 80, lv: 1, en: 'Do not stay behind; just keep practising a little every day.', zh: '不要落在后面，每天坚持练一点就好。', w: [94], note: '' },
  { id: 81, lv: 1, en: 'I believe that anyone can learn English well with enough practice.', zh: '我相信只要有足够练习，任何人都能学好英语。', w: [95], note: '' },
  { id: 82, lv: 1, en: 'She sat beside me and helped me with my pronunciation after class.', zh: '她坐在我旁边，课后帮我纠正发音。', w: [96], note: '' },
  { id: 83, lv: 1, en: 'He rides his bike to school even when the weather is cold.', zh: '即使天气冷，他也骑自行车上学。', w: [97], note: 'even when 即使当……时' },
  { id: 84, lv: 1, en: 'A little bird sings outside my window every early morning in spring.', zh: '春天每天清晨都有一只小鸟在我窗外唱歌。', w: [98], note: '' },
  { id: 85, lv: 1, en: 'My sister got an English novel as a birthday present last week.', zh: '我妹妹上周收到一本英文小说当生日礼物。', w: [99], note: 'as a present 作为礼物' },
  { id: 86, lv: 1, en: 'She writes her new words in a blue notebook so she can review them.', zh: '她把生词写在蓝色笔记本里，方便复习。', w: [100], note: '' },
  { id: 87, lv: 1, en: 'We took a small boat across the river to the old town.', zh: '我们坐小船过河去了老城区。', w: [101], note: '' },
  { id: 88, lv: 1, en: 'A healthy body helps you stay focused while you are studying for hours.', zh: '健康的身体能让你在长时间学习时保持专注。', w: [102], note: 'stay focused 保持专注' },
  { id: 89, lv: 1, en: 'You can borrow three English books from the library at a time.', zh: '你一次可以从图书馆借三本英语书。', w: [103], note: 'at a time 一次' },
  { id: 90, lv: 1, en: 'He keeps a bottle of water on his desk while he is working.', zh: '他工作时桌上总放着一瓶水。', w: [104], note: '' },
  { id: 91, lv: 1, en: 'I usually have bread and milk for breakfast before I go to work.', zh: '我上班前通常吃面包喝牛奶当早餐。', w: [105], note: 'have ... for breakfast 早餐吃……' },
  { id: 92, lv: 1, en: 'Let us take a short break and come back to this lesson later.', zh: '我们休息一小会儿，稍后再回到这节课。', w: [106], note: 'take a break 休息一下' },
  { id: 93, lv: 1, en: 'She listens to English podcasts while she is having breakfast every morning.', zh: '她每天早上吃早饭时听英语播客。', w: [107], note: 'while 引导时间状语从句' },
  { id: 94, lv: 1, en: 'The old bridge over the river was built more than fifty years ago.', zh: '河上那座老桥建于五十多年前。', w: [108], note: '被动语态 + 过去时间状语' },
  { id: 95, lv: 1, en: 'My younger brother practises English with me for half an hour every evening.', zh: '我弟弟每天晚上和我一起练半小时英语。', w: [109], note: '' },
  { id: 96, lv: 1, en: 'We should build good study habits before the exam gets any closer.', zh: '我们应该在考试临近前就养成良好的学习习惯。', w: [110], note: '' },
  { id: 97, lv: 1, en: 'He is too busy to watch TV, but he still reads at night.', zh: '他太忙没时间看电视，但晚上仍然读书。', w: [111], note: 'too ... to ... 太……而不能' },
  { id: 98, lv: 1, en: 'My mother made a chocolate cake for my birthday yesterday evening.', zh: '妈妈昨天晚上为我的生日做了一个巧克力蛋糕。', w: [112], note: '' },
  { id: 99, lv: 1, en: 'He used his new camera to take photos of the old streets.', zh: '他用新相机拍了那些老街道的照片。', w: [113], note: 'use sth. to do 用某物做' },
  { id: 100, lv: 1, en: 'The boy in the red cap is my classmate from middle school.', zh: '戴红帽子的那个男孩是我中学同学。', w: [114], note: 'in + 衣物/颜色 表示穿着' },
  { id: 101, lv: 1, en: 'I write each new word on a small card and review it later.', zh: '我把每个生词写在一张小卡片上，之后再复习。', w: [115], note: '' },
  { id: 102, lv: 1, en: 'Good teachers care about how their students feel, not only their scores.', zh: '好老师关心学生的感受，而不只是分数。', w: [116], note: 'care about 关心' },
  { id: 103, lv: 1, en: 'Be careful with the spelling when you write these long words down.', zh: '抄写这些长单词时要注意拼写。', w: [117], note: 'be careful with 小心……' },
  { id: 104, lv: 1, en: 'I always carry a small notebook to write down new words I hear.', zh: '我总是随身带个小本子，记下听到的生词。', w: [118], note: 'write down 写下' },
  { id: 105, lv: 1, en: 'I got up early so that I could catch the first bus.', zh: '我起得很早，以便赶上第一班公交车。', w: [119], note: 'so that 以便（目的状语从句）' },
  { id: 106, lv: 1, en: 'Small mistakes in pronunciation can cause misunderstanding during a conversation.', zh: '发音上的小错误会在对话中造成误解。', w: [120], note: '' },
  { id: 107, lv: 1, en: 'We will celebrate the end of the term with a small party.', zh: '我们要办个小聚会庆祝学期结束。', w: [121], note: '' },
  { id: 108, lv: 1, en: 'The new library stands in the center of our small quiet town.', zh: '新图书馆坐落在我们安静小镇的中心。', w: [122], note: '' },
  { id: 109, lv: 1, en: 'Please give him a chance to explain why he was late again.', zh: '请给他一个机会解释他为什么又迟到了。', w: [123], note: '' },
  { id: 110, lv: 1, en: 'It is never too late to change the way you learn new words.', zh: '改变学单词的方式永远都不晚。', w: [124], note: 'never too ... to 再……也不为过' },
  { id: 111, lv: 1, en: 'I often chat with my classmates in English after the evening class.', zh: '晚课后我常和同学用英语聊天。', w: [125], note: 'chat with sb. 和某人聊天' },
  { id: 112, lv: 1, en: 'These English magazines are cheap and easy to find in the store.', zh: '这些英语杂志很便宜，店里也容易买到。', w: [126], note: '' },
  { id: 113, lv: 1, en: 'Please check your answers again before you hand in the paper.', zh: '交卷前请再检查一遍答案。', w: [127], note: 'hand in 上交' },
  { id: 114, lv: 1, en: 'Every child in this class has a different way of learning words.', zh: '班上每个孩子记单词的方式都不一样。', w: [128], note: '' },
  { id: 115, lv: 1, en: 'You can choose any topic you like for the talk tomorrow morning.', zh: '明天上午的发言你可以选任何喜欢的话题。', w: [129], note: '' },
  { id: 116, lv: 1, en: 'This city has become much cleaner and safer over the last few years.', zh: '过去几年这座城市变得更加干净、安全。', w: [130], note: 'over the last few years 与现在完成时连用' },
  { id: 117, lv: 1, en: 'Our class starts at eight, so please do not be late again.', zh: '我们八点上课，所以请别再迟到了。', w: [131], note: '' },
  { id: 118, lv: 1, en: 'Keep your desk clean and you will find studying much easier.', zh: '保持书桌整洁，你会发现学习轻松很多。', w: [132], note: '祈使句 + and + 结果句' },
  { id: 119, lv: 1, en: 'The teacher gave us a clear example so everyone could understand quickly.', zh: '老师给了一个清晰的例子，好让大家快速理解。', w: [133], note: '' },
  { id: 120, lv: 1, en: 'She is clever enough to guess the meaning from the context around it.', zh: '她足够聪明，能从上下文猜出词义。', w: [134], note: 'adj. + enough to do' },
  { id: 121, lv: 1, en: 'We plan to climb the small hill behind our school this weekend.', zh: '我们计划这周末爬学校后面那座小山。', w: [135], note: '' },
  { id: 122, lv: 1, en: 'The old clock on the wall reminds me to review my words.', zh: '墙上的老钟提醒我复习单词。', w: [136], note: 'remind sb. to do 提醒某人做' },
  { id: 123, lv: 1, en: 'Please close the door quietly when you leave the classroom this evening.', zh: '今晚离开教室时请轻轻关门。', w: [137], note: '' },
  { id: 124, lv: 1, en: 'She bought some warm clothes for the cold winter in the north.', zh: '她为北方寒冷的冬天买了些保暖衣物。', w: [138], note: '' },
  { id: 125, lv: 1, en: 'Dark clouds are moving in, so we should go home right now.', zh: '乌云正在聚拢，我们得马上回家。', w: [139], note: '' },
  { id: 126, lv: 1, en: 'He drinks a cup of coffee while he reads the morning news online.', zh: '他边喝咖啡边看网络早间新闻。', w: [140], note: '' },
  { id: 127, lv: 1, en: 'It was so cold this morning that I kept my hands in my pockets.', zh: '今天早上冷得我一直把手插在口袋里。', w: [141], note: 'so ... that ... 如此……以至于' },
  { id: 128, lv: 1, en: 'She likes to collect English sayings in a small notebook with pictures.', zh: '她喜欢把英语谚语收集在带插画的小本子里。', w: [142], note: '' },
  { id: 129, lv: 1, en: 'What color is the bag you bought at the market last week?', zh: '你上周在市场买的那个包是什么颜色的？', w: [143], note: '' },
  { id: 130, lv: 1, en: 'Find a comfortable chair and read aloud for twenty minutes every evening.', zh: '找把舒服的椅子，每晚朗读二十分钟。', w: [144], note: '' },
  { id: 131, lv: 1, en: 'These common words appear in almost every English conversation you will hear.', zh: '这些常见词几乎出现在你会听到的每一段英语对话里。', w: [145], note: '' },
  { id: 132, lv: 1, en: 'Compare your answer with the one at the back of the book.', zh: '把你的答案和书后面的答案对比一下。', w: [146], note: 'compare A with B' },
  { id: 133, lv: 1, en: 'You should complete all the exercises before the next class begins.', zh: '你应该在下节课开始前完成所有练习。', w: [147], note: '' },
  { id: 134, lv: 1, en: 'My computer broke down, so I wrote the new words down by hand.', zh: '我的电脑坏了，所以只能手抄生词。', w: [148], note: 'break down 出故障' },
  { id: 135, lv: 1, en: 'We went to a small concert in the park after dinner yesterday.', zh: '昨天晚饭后我们去了公园里的小型音乐会。', w: [149], note: '' },
  { id: 136, lv: 1, en: 'My father likes to cook simple meals while listening to English songs.', zh: '我爸爸喜欢边听英文歌边做简单的饭菜。', w: [150], note: '' },
  { id: 137, lv: 1, en: 'The evening air is cool, so let us study outside for a while.', zh: '傍晚空气很凉爽，我们到外面学一会儿吧。', w: [151], note: '' },
  { id: 138, lv: 1, en: 'There is a quiet corner in the library where I often read aloud.', zh: '图书馆里有个安静的角落，我常在那里朗读。', w: [152], note: 'where 引导定语从句' },
  { id: 139, lv: 1, en: 'The cost of living in this city is higher than in my hometown.', zh: '这座城市的生活成本比我家乡高。', w: [153], note: 'the cost of living 生活成本' },
  { id: 140, lv: 1, en: 'Every minute counts when you are preparing for an important exam.', zh: '准备重要考试时每分钟都很重要。', w: [154], note: '' },
  { id: 141, lv: 1, en: 'This country has a long history and many beautiful old towns.', zh: '这个国家历史悠久，还有许多美丽的古镇。', w: [155], note: '' },
  { id: 142, lv: 1, en: 'I signed up for an online course to improve my spoken English.', zh: '我报名了一门线上课程来提高英语口语。', w: [156, 1], note: 'sign up for 报名参加' },
  { id: 143, lv: 1, en: 'My cousin and I studied English together during the long summer holiday.', zh: '漫长的暑假里，我和表弟一起学英语。', w: [157], note: '' },
  { id: 144, lv: 1, en: 'Do not cry over a low score; just find out what went wrong.', zh: '别为低分哭泣，弄清哪里出了问题就好。', w: [158], note: 'find out 查明' },
  { id: 145, lv: 1, en: 'You can cut the long article into short parts to read it.', zh: '你可以把长文章切成小段来读。', w: [159], note: 'cut ... into 把……切成' },
  { id: 146, lv: 1, en: 'The children dance and sing in the hall every Friday afternoon.', zh: '孩子们每周五下午在礼堂里唱歌跳舞。', w: [160], note: '' },
  { id: 147, lv: 1, en: 'The sign by the river warns people of the danger ahead.', zh: '河边的标识提醒人们前方有危险。', w: [161], note: 'warn sb. of 提醒某人注意' },
  { id: 148, lv: 1, en: 'It gets dark early in winter, so I read at home instead.', zh: '冬天黑得早，所以我改在家里读书。', w: [162], note: '' },
  { id: 149, lv: 1, en: 'We set a date for the next meeting and wrote it down.', zh: '我们定好了下次开会日期并记了下来。', w: [163], note: '' },
  { id: 150, lv: 1, en: 'His daughter reads English stories to him before she goes to bed.', zh: '他女儿睡前给他读英文故事。', w: [164], note: '' },
  { id: 151, lv: 1, en: 'You must decide which words to review first before the coming test.', zh: '你必须决定在即将到来的考试前先复习哪些单词。', w: [165], note: '' },
  { id: 152, lv: 1, en: 'The bread from that small shop is cheap and really delicious.', zh: '那家小店的面包便宜又好吃。', w: [166, 126], note: '' },
  { id: 153, lv: 1, en: 'I keep a small dictionary on my desk for quick checks during reading.', zh: '我在桌上放一本小词典，阅读时快速查词。', w: [167, 168], note: '' },
  { id: 154, lv: 1, en: 'A good dictionary tells you how a word is really used in sentences.', zh: '一本好词典会告诉你单词在句子中的真实用法。', w: [168], note: '' },
  { id: 155, lv: 1, en: 'Our family talks about the day over dinner every single evening.', zh: '我们家每天晚饭时都会聊聊这一天。', w: [169], note: 'over dinner 吃饭时' },
  { id: 156, lv: 1, en: 'You will discover that reading gets much easier after a few weeks.', zh: '你会发现几周之后阅读变得容易多了。', w: [170], note: '' },
  { id: 157, lv: 1, en: 'The doctor told him to rest more and work fewer hours each day.', zh: '医生让他多休息，每天少工作几小时。', w: [171], note: '' },
  { id: 158, lv: 1, en: 'Their dog follows them everywhere, even to the small park nearby.', zh: '他们的狗到哪儿都跟着，连附近的小公园也去。', w: [172], note: '' },
  { id: 159, lv: 1, en: 'Please knock on the door before you come into the office.', zh: '进办公室前请先敲门。', w: [173], note: 'knock on 敲（门）' },
  { id: 160, lv: 1, en: 'We went downstairs to the small cafe and talked for an hour.', zh: '我们下楼去了那家小咖啡馆，聊了一个小时。', w: [174], note: '' },
  { id: 161, lv: 1, en: 'Her dream is to study abroad and teach English to young children.', zh: '她的梦想是出国留学，然后教小孩子英语。', w: [175], note: '' },
  { id: 162, lv: 1, en: 'She wore a simple dress to the party and looked very happy.', zh: '她穿了一条简单的裙子去聚会，看起来很开心。', w: [176], note: '' },
  { id: 163, lv: 1, en: 'My uncle will drive us to the station early tomorrow morning.', zh: '叔叔明天一早会开车送我们去车站。', w: [177], note: '' },
  { id: 164, lv: 1, en: 'This lesson looks easy, but the new words are easy to forget.', zh: '这课看着简单，但生词很容易忘。', w: [178], note: '' },
  { id: 165, lv: 1, en: 'We usually eat at a small restaurant near the school gate.', zh: '我们常在校门口的小餐馆吃饭。', w: [179], note: '' },
  { id: 166, lv: 1, en: 'The classroom was empty, so I practised speaking English there alone.', zh: '教室空着，我就一个人在那里练英语口语。', w: [180], note: '' },
  { id: 167, lv: 1, en: 'At the end of the day, I write down five new words.', zh: '一天结束时，我会记下五个生词。', w: [181], note: 'at the end of 在……结束时' },
  { id: 168, lv: 1, en: 'I enjoy reading short stories more than long articles in English.', zh: '比起长篇英语文章，我更喜欢读短篇故事。', w: [182], note: 'enjoy doing 喜欢做' },
  { id: 169, lv: 1, en: 'We take a walk together in the evening and talk about our day.', zh: '我们傍晚一起散步，聊聊这一天。', w: [183], note: '' },
  { id: 170, lv: 1, en: 'The children were excited about the trip to the old museum.', zh: '孩子们对去老博物馆的行程很兴奋。', w: [184], note: 'be excited about 对……兴奋' },
  { id: 171, lv: 1, en: 'He made an excuse for not finishing his homework again yesterday.', zh: '昨天他又为没写完作业找了个借口。', w: [185], note: 'make an excuse 找借口' },
  { id: 172, lv: 1, en: 'Doing exercise for thirty minutes a day helps me sleep much better.', zh: '每天锻炼三十分钟让我睡得好多了。', w: [186], note: '动名词作主语' },
  { id: 173, lv: 1, en: 'That English dictionary is expensive, but it will last for many years.', zh: '那本英语词典很贵，但能用很多年。', w: [187], note: '' },
  { id: 174, lv: 1, en: 'Could you explain this long sentence to me in simpler English?', zh: '你能用更简单的英语给我解释这个长句吗？', w: [188], note: '' },
  { id: 175, lv: 1, en: 'Keep an eye on the words that you keep forgetting again and again.', zh: '留心那些你反复忘记的单词。', w: [189], note: 'keep an eye on 留意' },
  { id: 176, lv: 1, en: 'We must face the fact that learning a language takes real time.', zh: '我们必须面对这个事实：学语言真的需要时间。', w: [190], note: 'face the fact that 面对……的事实' },
  { id: 177, lv: 1, en: 'The leaves fall from the trees when autumn comes to this city.', zh: '秋天来临时，这座城市的树叶纷纷落下。', w: [191], note: '' },
  { id: 178, lv: 1, en: 'My whole family sits together and talks after dinner every night.', zh: '我们全家人每晚饭后都坐在一起聊天。', w: [192], note: '' },
  { id: 179, lv: 1, en: 'That small town is famous for its old bridge and quiet streets.', zh: '那个小镇以老桥和安静的街道闻名。', w: [193], note: 'be famous for 以……闻名' },
  { id: 180, lv: 1, en: 'The station is not far from here, so we can walk there.', zh: '车站离这儿不远，我们可以走过去。', w: [194], note: 'far from 离……远' },
  { id: 181, lv: 1, en: 'He reads very fast, but he sometimes misses the meaning of a sentence.', zh: '他读得很快，但有时会漏掉句子的意思。', w: [195], note: '' },
  { id: 182, lv: 1, en: 'The fat cat sleeps on the sofa all afternoon and never moves.', zh: '那只胖猫整个下午都睡在沙发上，一动不动。', w: [196], note: '' },
  { id: 183, lv: 1, en: 'This is my favorite English song, and I listen to it very often.', zh: '这是我最喜欢的英文歌，我常听。', w: [197], note: '' },
  { id: 184, lv: 1, en: 'I feel much better after a short walk in the fresh air.', zh: '在新鲜空气里走一小会儿，我感觉好多了。', w: [198], note: '' },
  { id: 185, lv: 1, en: 'The festival brings music, food and people together in the town square.', zh: '这个节日把音乐、美食和人们聚到镇上的广场。', w: [199], note: '' },
  { id: 186, lv: 1, en: 'Please finish the reading task before you go to bed tonight.', zh: '今晚睡前请完成阅读任务。', w: [200], note: '' },
  { id: 187, lv: 1, en: 'We had fish and rice for lunch at the small restaurant near school.', zh: '我们在学校附近的小餐馆吃了鱼和米饭当午餐。', w: [201], note: '' },
  { id: 188, lv: 1, en: 'My little brother dropped his English book on the floor again yesterday.', zh: '弟弟昨天又把英语书掉在地上了。', w: [202], note: '' },
  { id: 189, lv: 1, en: 'She put some fresh flowers on the table near the open window.', zh: '她在靠窗的桌上放了些鲜花。', w: [203], note: '' },
  { id: 190, lv: 1, en: 'Many birds fly south when the weather turns cold in the north.', zh: '北方天气转冷时，许多鸟飞往南方。', w: [204], note: '' },
  { id: 191, lv: 1, en: 'Follow the example sentence and then write one of your own.', zh: '仿照例句，然后自己写一个句子。', w: [205], note: '' },
  { id: 192, lv: 1, en: 'Do not forget to review the words you learned last week.', zh: '别忘了复习上周学的单词。', w: [206], note: 'forget to do 忘记去做' },
  { id: 193, lv: 1, en: 'Open the window and let some fresh air into the room.', zh: '打开窗户，让新鲜空气进到房间里。', w: [207], note: '' },
  { id: 194, lv: 1, en: 'A true friend will tell you when your pronunciation is really wrong.', zh: '真正的朋友会在你发音确实错误时告诉你。', w: [208], note: '' },

  // ---------- Lv2 扩充（对应新增基础词） ----------
  { id: 195, lv: 2, en: 'My teacher advised me to read short articles instead of long novels.', zh: '老师建议我读短篇文章，而不是长篇小说。', w: [209], note: 'advise sb. to do 建议某人做' },
  { id: 196, lv: 2, en: 'Lack of sleep can affect your memory during the long exam week.', zh: '睡眠不足会影响你在漫长考试周里的记忆力。', w: [210], note: '' },
  { id: 197, lv: 2, en: 'We cannot afford to waste another month on the wrong learning method.', zh: '我们浪费不起又一个月的错误学习方法。', w: [211], note: 'afford to do 负担得起做' },
  { id: 198, lv: 2, en: 'A large amount of reading will slowly build up your vocabulary.', zh: '大量的阅读会慢慢积累你的词汇量。', w: [212], note: 'a large amount of 大量的（修饰不可数）' },
  { id: 199, lv: 2, en: 'The school will announce the results of the speaking contest next Monday.', zh: '学校将于下周一公布演讲比赛结果。', w: [213], note: '' },
  { id: 200, lv: 2, en: 'She felt anxious before the interview, so she took a deep breath.', zh: '面试前她很焦虑，于是深吸了一口气。', w: [214], note: '' },
  { id: 201, lv: 2, en: 'You should apply what you have learned to real conversations as soon as possible.', zh: '你应该尽快把学到的东西用到真实对话里。', w: [215], note: 'apply ... to ... 把……应用于' },
  { id: 202, lv: 2, en: 'I really appreciate the help you gave me with my pronunciation.', zh: '非常感谢你在发音上给我的帮助。', w: [216], note: 'appreciate sth. 感激某事' },
  { id: 203, lv: 2, en: 'We need a different approach to remember words that keep slipping away.', zh: '我们需要换一种方法来记住总在遗忘的单词。', w: [217], note: 'an approach to 一种……的方法' },
  { id: 204, lv: 2, en: 'They argued about the best way to prepare for the coming exam.', zh: '他们为备考的最佳方式争论起来。', w: [218], note: 'argue about 就……争论' },
  { id: 205, lv: 2, en: 'Could you arrange a short meeting with the new English teacher this week?', zh: '这周你能安排一次和新英语老师的短会吗？', w: [219], note: '' },
  { id: 206, lv: 2, en: 'More than two hundred students attended the talk on learning methods.', zh: '两百多名学生参加了这场关于学习方法的讲座。', w: [220], note: '' },
  { id: 207, lv: 2, en: 'Free online materials are available to anyone with a phone and network.', zh: '只要有手机和网络，任何人都能获得免费的线上资料。', w: [221], note: 'be available to sb. 对某人可用' },
  { id: 208, lv: 2, en: 'On average, he reviews about thirty new words every single day.', zh: '他平均每天复习大约三十个生词。', w: [222], note: 'on average 平均' },
  { id: 209, lv: 2, en: 'Try to keep a balance between new words and regular review time.', zh: '努力在新词学习和常规复习之间保持平衡。', w: [223], note: 'keep a balance between A and B' },
  { id: 210, lv: 2, en: 'Reading aloud every morning will benefit your speaking more than you think.', zh: '每天早上朗读对口语的好处超乎你的想象。', w: [224], note: '' },
  { id: 211, lv: 2, en: 'Please give a brief answer so we can move on to the next question.', zh: '请简要回答，我们好进到下一个问题。', w: [225], note: '' },
  { id: 212, lv: 2, en: 'Our family budget does not allow us to buy many new books this month.', zh: '家里的预算不允许我们这个月买很多新书。', w: [226], note: '' },
  { id: 213, lv: 2, en: 'Stay calm and read the question twice before you choose an answer.', zh: '保持冷静，把题目读两遍再选答案。', w: [227], note: '' },
  { id: 214, lv: 2, en: 'We had to cancel the outdoor activity because of the heavy rain.', zh: '因为大雨我们不得不取消户外活动。', w: [228], note: 'because of + 名词' },
  { id: 215, lv: 2, en: 'Every candidate must arrive fifteen minutes before the interview begins.', zh: '每位应试者都必须在面试开始前十五分钟到达。', w: [229], note: '' },
  { id: 216, lv: 2, en: 'A good career usually starts with small steps that nobody notices.', zh: '好的职业往往始于没人注意的一小步。', w: [230], note: '' },
  { id: 217, lv: 2, en: 'I am certain that you will pass if you keep this pace.', zh: '我确信只要你保持这个节奏就能通过。', w: [231], note: 'be certain that 确信' },
  { id: 218, lv: 2, en: 'My colleague lent me an old notebook full of useful example sentences.', zh: '同事借给我一本写满实用例句的旧笔记本。', w: [232], note: '' },
  { id: 219, lv: 2, en: 'You can combine short daily reviews with one longer session at weekends.', zh: '你可以把每天的小复习和周末一次长复习结合起来。', w: [233], note: 'combine A with B' },
  { id: 220, lv: 2, en: 'A few kind words can bring real comfort to someone under pressure.', zh: '几句温暖的话能给压力中的人真正的安慰。', w: [234], note: '' },
  { id: 221, lv: 2, en: 'The teacher wrote a short comment under each of my answers.', zh: '老师在每个答案下面都写了简短的评语。', w: [235], note: '' },
  { id: 222, lv: 2, en: 'If you commit two hours a day, your English will change fast.', zh: '如果你每天投入两小时，英语会变化很快。', w: [236], note: 'commit time to sth. 投入时间' },
  { id: 223, lv: 2, en: 'Small local shops have to compete with big stores on price and speed.', zh: '本地小店不得不在价格和速度上与大店竞争。', w: [237], note: 'compete with 与……竞争' },
  { id: 224, lv: 2, en: 'Students often complain that they forget new words the very next day.', zh: '学生常抱怨第二天就把生词忘光了。', w: [238], note: 'complain that 抱怨' },
  { id: 225, lv: 2, en: 'It is hard to concentrate when your phone keeps lighting up beside you.', zh: '手机在旁边不停亮起时很难集中注意力。', w: [239], note: '' },
  { id: 226, lv: 2, en: 'From these facts we can conclude that review matters more than speed.', zh: '从这些事实可以得出结论：复习比速度更重要。', w: [240], note: 'conclude that 得出结论' },
  { id: 227, lv: 2, en: 'The team will conduct a short survey among all the first-year students.', zh: '团队将在所有一年级学生中做一次简短调查。', w: [241], note: '' },
  { id: 228, lv: 2, en: 'Please confirm your name and class before the result is sent out.', zh: '成绩发布前请确认你的姓名和班级。', w: [242], note: '' },
  { id: 229, lv: 2, en: 'Try to connect each new word with a picture in your mind.', zh: '试着把每个生词和你脑中的画面联系起来。', w: [243], note: 'connect A with B' },
  { id: 230, lv: 2, en: 'We should consider the feelings of others before we say something sharp.', zh: '说话刻薄之前，我们应该考虑别人的感受。', w: [244], note: '' },
  { id: 231, lv: 2, en: 'This short article contains almost all the words we learned last month.', zh: '这篇短文几乎包含了我们上个月学的所有单词。', w: [245], note: '' },
  { id: 232, lv: 2, en: 'If you continue this habit, your listening will improve within two months.', zh: '如果你坚持这个习惯，听力会在两个月内提高。', w: [246, 1], note: '' },
  { id: 233, lv: 2, en: 'Read the contract carefully before you sign your name at the bottom.', zh: '在末尾签名前请仔细阅读合同。', w: [247], note: '' },
  { id: 234, lv: 2, en: 'You cannot control everything, but you can control how you respond.', zh: '你无法控制一切，但可以控制自己的反应。', w: [248], note: '' },
  { id: 235, lv: 2, en: 'Online dictionaries are convenient when you read on the bus or subway.', zh: '在公交或地铁上阅读时，在线词典很方便。', w: [249], note: '' },
  { id: 236, lv: 2, en: 'He convinced me that speaking aloud is better than silent reading alone.', zh: '他让我相信朗读比单纯默读更好。', w: [250], note: 'convince sb. that 使某人相信' },
  { id: 237, lv: 2, en: 'It takes courage to correct your own mistakes in front of others.', zh: '在别人面前纠正自己的错误需要勇气。', w: [251], note: '' },
  { id: 238, lv: 2, en: 'The app lets you create your own word list for each week.', zh: '这款应用可以让你为每周创建自己的单词表。', w: [252], note: '' },
  { id: 239, lv: 2, en: 'Every customer wants to be heard, not just to be answered quickly.', zh: '每位顾客都希望被倾听，而不仅是被快速回应。', w: [253], note: '' },
  { id: 240, lv: 2, en: 'One careless word can damage a friendship that took years to build.', zh: '一句无心的话可能损害经营多年的友谊。', w: [254], note: '' },
  { id: 241, lv: 2, en: 'We have to deal with these small problems before they grow bigger.', zh: '我们必须在小问题变大之前处理掉它们。', w: [255], note: 'deal with 处理' },
  { id: 242, lv: 2, en: 'The shop promises to deliver the books to your door within two days.', zh: '书店承诺两天内把书送到你家门口。', w: [256], note: '' },
  { id: 243, lv: 2, en: 'The demand for English speaking skills keeps growing in many cities.', zh: '许多城市对英语口语能力的需求持续增长。', w: [257], note: 'demand for 对……的需求' },
  { id: 244, lv: 2, en: 'Your result will depend on how much real practice you do.', zh: '你的成绩取决于你做了多少真正的练习。', w: [258], note: 'depend on 取决于' },
  { id: 245, lv: 2, en: 'Can you describe the picture in English using at least five sentences?', zh: '你能用至少五句话用英语描述这幅图吗？', w: [259], note: '' },
  { id: 246, lv: 2, en: 'The course is designed for people who already know the basic words.', zh: '这门课是为已掌握基础词汇的人设计的。', w: [260], note: 'be designed for 为……设计' },
  { id: 247, lv: 2, en: 'Let us first determine what the real problem is before acting.', zh: '行动前我们先确定真正的问题是什么。', w: [261], note: '' },
  { id: 248, lv: 2, en: 'We will discuss the answers together after everyone finishes the exercise.', zh: '大家做完练习后我们会一起讨论答案。', w: [262], note: '' },
  { id: 249, lv: 2, en: 'There is no doubt that daily reading shapes the way you write.', zh: '毫无疑问，每日阅读塑造你的写作方式。', w: [263], note: 'there is no doubt that 毫无疑问' },
  { id: 250, lv: 2, en: 'Students who review regularly earn better grades than those who cram.', zh: '定期复习的学生成绩好过临时抱佛脚的。', w: [264], note: '' },
  { id: 251, lv: 2, en: 'Reading aloud has a strong effect on how well you remember words.', zh: '朗读对你记单词的效果有很大影响。', w: [265], note: 'have an effect on 对……有影响' },
  { id: 252, lv: 2, en: 'Call this number at once if there is any kind of emergency.', zh: '如有任何紧急情况，请立刻拨打这个号码。', w: [266], note: '' },
  { id: 253, lv: 2, en: 'The company plans to employ twenty new guides for the busy season.', zh: '公司计划在旺季雇用二十名新导游。', w: [267], note: '' },
  { id: 254, lv: 2, en: 'Parents should encourage children to read for pleasure, not only for exams.', zh: '父母应鼓励孩子为乐趣而读，而不只为考试。', w: [268], note: 'encourage sb. to do' },
  { id: 255, lv: 2, en: 'She puts a lot of energy into preparing each short listening task.', zh: '她为每个短听力任务投入大量精力。', w: [269], note: 'put energy into 把精力投入' },
  { id: 256, lv: 2, en: 'Please ensure that your name is written clearly on the answer sheet.', zh: '请确保答题卡上姓名写得清楚。', w: [270], note: '' },
  { id: 257, lv: 2, en: 'His enthusiasm for English started with one short story in middle school.', zh: '他对英语的热情始于中学时的一篇短篇小说。', w: [271], note: 'enthusiasm for 对……的热情' },
  { id: 258, lv: 2, en: 'In this class everyone is equal, and every question is worth asking.', zh: '在这个班上人人平等，每个问题都值得提出。', w: [272], note: '' },
  { id: 259, lv: 2, en: 'The school bought new equipment for the language lab last summer.', zh: '学校去年夏天为语音室购置了新设备。', w: [273], note: '' },
  { id: 260, lv: 2, en: 'Reading stories is a cheap way to escape from a busy week.', zh: '读故事是从忙碌一周中抽身的廉价方式。', w: [274], note: '' },
  { id: 261, lv: 2, en: 'We estimate that this lesson will take about forty minutes in total.', zh: '我们估计这节课总共大约需要四十分钟。', w: [275], note: '' },
  { id: 262, lv: 2, en: 'The teacher will examine how you use these words in real sentences.', zh: '老师会考查你在真实句子中如何使用这些词。', w: [276], note: '' },
  { id: 263, lv: 2, en: 'Our school runs an exchange programme with a small college abroad.', zh: '我们学校与国外一所小型学院有交流项目。', w: [277], note: '' },
  { id: 264, lv: 2, en: 'Do not expect to remember a word after meeting it only once.', zh: '别指望只见过一次就记住一个单词。', w: [278], note: 'expect to do 期待做' },
  { id: 265, lv: 2, en: 'The monthly expense of the club is small, so anyone can join.', zh: '俱乐部每月开支很小，任何人都能加入。', w: [279], note: '' },
  { id: 266, lv: 2, en: 'Weekends are a good time to explore the old streets near the river.', zh: '周末是探索河边老街的好时候。', w: [280], note: '' },
  { id: 267, lv: 2, en: 'Try to express one simple idea clearly instead of three vague ones.', zh: '试着把一个简单的想法说清楚，而不是说三个含糊的。', w: [281], note: '' },
  { id: 268, lv: 2, en: 'They decided to extend the reading time from ten to twenty minutes.', zh: '他们决定把阅读时间从十分钟延长到二十分钟。', w: [282], note: 'extend ... from ... to ...' },
  { id: 269, lv: 2, en: 'Interest is the biggest factor in how fast a child learns words.', zh: '兴趣是孩子记单词速度的最大因素。', w: [283], note: '' },
  { id: 270, lv: 2, en: 'After a few weeks these words will become familiar to most students.', zh: '几周后这些单词对多数学生来说就会变得熟悉。', w: [284], note: 'be familiar to sb. 为某人所熟悉' },
  { id: 271, lv: 2, en: 'One useful feature of this app is the daily review reminder.', zh: '这款应用的一个实用功能是每日复习提醒。', w: [285], note: '' },
  { id: 272, lv: 2, en: 'The course fee includes all the books and the final speaking test.', zh: '课程费用包含所有教材和最后的口语测试。', w: [286], note: '' },
  { id: 273, lv: 2, en: 'She works in finance, but she reads English novels every night.', zh: '她做金融工作，但每晚读英文小说。', w: [287], note: '' },
  { id: 274, lv: 2, en: 'Find a method that fits your schedule instead of copying someone else.', zh: '找一个适合你时间的方法，而不是照搬别人的。', w: [288], note: '' },
  { id: 275, lv: 2, en: 'Focus on the words that appear most often in everyday conversations.', zh: '把注意力放在日常对话中出现最频繁的词上。', w: [289], note: 'focus on 专注于' },
  { id: 276, lv: 2, en: 'School rules forbid students to use phones during the morning reading.', zh: '校规禁止学生在晨读时使用手机。', w: [290], note: 'forbid sb. to do 禁止某人做' },
  { id: 277, lv: 2, en: 'The heart of the app is a simple function: it reminds you to review.', zh: '这款应用的核心是一个简单功能：提醒你复习。', w: [291], note: '' },
  { id: 278, lv: 2, en: 'You will gain confidence every time you finish a short English task.', zh: '每完成一次小英语任务，你都会收获自信。', w: [292, 15], note: '' },
  { id: 279, lv: 2, en: 'This generation learns words through short videos more than through books.', zh: '这一代人通过短视频学词多于通过书本。', w: [293], note: '' },
  { id: 280, lv: 2, en: 'She showed genuine interest in every student who asked a question.', zh: '她对每一个提问的学生都表现出真诚的兴趣。', w: [294], note: '' },
  { id: 281, lv: 2, en: 'He will graduate next summer and hopes to work with foreign teams.', zh: '他明年夏天毕业，希望能与外国团队合作。', w: [295], note: '' },
  { id: 282, lv: 2, en: 'The school granted him a small sum of money for his project.', zh: '学校为他的项目拨了一小笔钱。', w: [296], note: '' },
  { id: 283, lv: 2, en: 'No method can guarantee progress if you never open the book.', zh: '如果你从不翻开书，任何方法都无法保证进步。', w: [297], note: '' },
  { id: 284, lv: 2, en: 'Learn to handle pressure calmly, and the exam becomes much easier.', zh: '学会冷静应对压力，考试就会轻松很多。', w: [298], note: '' },
  { id: 285, lv: 2, en: 'A few careless words can harm a relationship more than silence.', zh: '几句无心的话比沉默更能伤害一段关系。', w: [299], note: '' },
  { id: 286, lv: 2, en: 'They hired two new teachers to start the speaking course this term.', zh: '他们聘了两位新老师在本学期开口语课。', w: [300], note: '' },
  { id: 287, lv: 2, en: 'To be honest, I forgot most of the words I learned last year.', zh: '说实话，去年学的单词我大多忘了。', w: [301], note: 'to be honest 说实话' },
  { id: 288, lv: 2, en: 'Good readers identify the main idea before they worry about new words.', zh: '好的读者在纠结生词之前会先找出主旨。', w: [302], note: '' },
  { id: 289, lv: 2, en: 'If you ignore small mistakes, they will grow into big habits.', zh: '如果你忽视小错误，它们会变成大习惯。', w: [303], note: '' },
  { id: 290, lv: 2, en: 'The chart illustrates how often each word appears in daily speech.', zh: '这张图表说明了每个词在日常口语中出现的频率。', w: [304], note: '' },
  { id: 291, lv: 2, en: 'Can you imagine reading a whole English novel without any dictionary?', zh: '你能想象不用词典读完一整本英文小说吗？', w: [305], note: 'imagine doing 想象做' },
  { id: 292, lv: 2, en: 'The app gives immediate feedback, so you know the answer at once.', zh: '这款应用会立即反馈，你马上就知道答案。', w: [306], note: '' },
  { id: 293, lv: 2, en: 'His silence seems to imply that he does not agree with us.', zh: '他的沉默似乎暗示他并不赞同我们。', w: [307], note: '' },
  { id: 294, lv: 2, en: 'She impressed the judges with a short but very clear answer.', zh: '她用简短而清晰的回答给评委留下印象。', w: [308], note: 'impress sb. with 以……打动某人' },
  { id: 295, lv: 2, en: 'Recent studies indicate that short reviews work better than long ones.', zh: '近期研究表明短时复习比长时复习更有效。', w: [309], note: '' },
  { id: 296, lv: 2, en: 'The tourist industry here needs more people who speak good English.', zh: '这里的旅游业需要更多英语好的人。', w: [310], note: '' },
  { id: 297, lv: 2, en: 'Please inform us if you cannot attend the speaking class on time.', zh: '如果你不能按时上口语课，请告知我们。', w: [311, 220], note: '' },
  { id: 298, lv: 2, en: 'She insisted on reviewing every word before she closed the notebook.', zh: '她坚持在合上笔记本前复习每一个单词。', w: [312], note: 'insist on doing 坚持做' },
  { id: 299, lv: 2, en: 'You can install the dictionary on your phone in less than a minute.', zh: '你不到一分钟就能把词典装到手机上。', w: [313], note: '' },
  { id: 300, lv: 2, en: 'I intend to read one short English article every day this year.', zh: '我打算今年每天读一篇英语短文。', w: [314], note: 'intend to do 打算做' },
  { id: 301, lv: 2, en: 'The interview lasted only ten minutes, but it decided everything.', zh: '面试只持续了十分钟，却决定了一切。', w: [315], note: '' },
  { id: 302, lv: 2, en: 'Let me introduce a simple way to take notes during listening practice.', zh: '我来介绍一种听力练习时做笔记的简单方法。', w: [316], note: '' },
  { id: 303, lv: 2, en: 'You should invest at least twenty minutes in review every evening.', zh: '你每晚至少应投入二十分钟复习。', w: [317], note: 'invest time in 把时间投入' },
  { id: 304, lv: 2, en: 'Good lessons involve questions, not just answers copied from a book.', zh: '好的课堂包含提问，而不只是照搬书上的答案。', w: [318], note: '' },
  { id: 305, lv: 2, en: 'The real issue is not time, but the way we use it.', zh: '真正的问题不是时间，而是我们使用时间的方式。', w: [319], note: '' },
  { id: 306, lv: 2, en: 'Do not judge a learner by how fast he answers the question.', zh: '别以答题速度来评判一个学习者。', w: [320], note: 'judge ... by 以……评判' },
  { id: 307, lv: 2, en: 'Put a label on each notebook so you can find your notes quickly.', zh: '给每个笔记本贴上标签，方便快速找到笔记。', w: [321], note: '' },
  { id: 308, lv: 2, en: 'Learning a language is mostly quiet labour that nobody else sees.', zh: '学语言多半是别人看不见的默默付出。', w: [322], note: '' },
  { id: 309, lv: 2, en: 'The club will launch a new reading programme at the start of term.', zh: '俱乐部将在学期初推出新的阅读计划。', w: [323], note: '' },
  { id: 310, lv: 2, en: 'Every worker has the legal right to a safe and healthy workplace.', zh: '每位劳动者都享有安全健康工作环境的合法权利。', w: [324], note: '' },
  { id: 311, lv: 2, en: 'Set a clear limit on screen time, or reading time will disappear.', zh: '给屏幕时间设个明确上限，否则阅读时间就没了。', w: [325], note: '' },
  { id: 312, lv: 2, en: 'Can you locate the main idea in the second paragraph of the text?', zh: '你能找出文章第二段的主旨吗？', w: [326], note: '' },
  { id: 313, lv: 2, en: 'He manages his study time with a simple list stuck on the wall.', zh: '他用贴在墙上的简单清单管理学习时间。', w: [327], note: '' },
  { id: 314, lv: 2, en: 'She answered in a polite manner that everyone in the room noticed.', zh: '她回答得很礼貌，在场的人都注意到了。', w: [328], note: 'in a ... manner 以……的方式' },
  { id: 315, lv: 2, en: 'The best measure of progress is how much you can use, not recall.', zh: '衡量进步最好的标准是你能用多少，而非回想多少。', w: [329], note: '' },
  { id: 316, lv: 2, en: 'He mentioned three small habits that helped him remember new words.', zh: '他提到三个帮他记生词的小习惯。', w: [330], note: '' },
  { id: 317, lv: 2, en: 'This method works well for people who like short daily practice.', zh: '这个方法对喜欢每天短时练习的人很有效。', w: [331], note: 'work well for 对……有效' },
  { id: 318, lv: 2, en: 'The app can monitor how many new words you review each week.', zh: '这款应用可以监测你每周复习了多少生词。', w: [332], note: '' },
  { id: 319, lv: 2, en: 'There is a moral lesson in that story about patience and honesty.', zh: '那个故事里有一个关于耐心和诚实的道德启示。', w: [333], note: '' },
  { id: 320, lv: 2, en: 'We need to negotiate a time that suits both our busy schedules.', zh: '我们需要商量一个适合双方忙碌日程的时间。', w: [334], note: '' },
  { id: 321, lv: 2, en: 'It is normal to forget a word you met only once or twice.', zh: '忘掉只见过一两次的单词是很正常的。', w: [335], note: 'It is normal to do 做……很正常' },
  { id: 322, lv: 2, en: 'Did you notice how often this word appears in everyday conversations?', zh: '你注意到这个词在日常对话中出现得有多频繁吗？', w: [336], note: '' },
  { id: 323, lv: 2, en: 'You can obtain a free copy of the word list from the office.', zh: '你可以从办公室免费领取一份单词表。', w: [337], note: '' },
  { id: 324, lv: 2, en: 'It is obvious that he has read this article more than once.', zh: '显然这篇文章他不止读过一遍。', w: [338], note: 'It is obvious that 显然' },
  { id: 325, lv: 2, en: 'Phones occupy too much of the time we could spend reading quietly.', zh: '手机占用了太多本可以用来安静阅读的时间。', w: [339], note: '' },
  { id: 326, lv: 2, en: 'The library will operate longer hours during the busy exam period.', zh: '图书馆将在繁忙的考试期间延长开放时间。', w: [340], note: '' },
  { id: 327, lv: 2, en: 'Many parents oppose the idea of more homework at the weekend.', zh: '许多家长反对周末布置更多作业的想法。', w: [341], note: '' },
  { id: 328, lv: 2, en: 'Try to organize your notes by topic so review becomes much faster.', zh: '试着按主题整理笔记，复习会快很多。', w: [342], note: '' },
  { id: 329, lv: 2, en: 'Students who participate actively usually remember the words much longer.', zh: '积极参与的学生通常记单词记得久得多。', w: [343], note: '' },
  { id: 330, lv: 2, en: 'Be patient with yourself; a language grows slowly, like a small tree.', zh: '对自己耐心些；语言像小树一样慢慢长大。', w: [344], note: 'be patient with 对……有耐心' },
  { id: 331, lv: 2, en: 'Try to notice the pattern behind words that share the same ending.', zh: '留意词尾相同的单词背后的规律。', w: [345], note: '' },
  { id: 332, lv: 2, en: 'Most students perform better in the morning than late in the evening.', zh: '多数学生早晨的表现好过深夜。', w: [346], note: '' },
  { id: 333, lv: 2, en: 'The rules do not permit phones inside the examination hall at all.', zh: '规定完全不允许把手机带进考场。', w: [347], note: '' },
  { id: 334, lv: 2, en: 'It is hard to persuade someone who has already made up his mind.', zh: '很难说服一个已经下定决心的人。', w: [348], note: 'persuade sb. 说服某人' },
  { id: 335, lv: 2, en: 'The new school policy allows students to read during the long break.', zh: '学校新政策允许学生在长课间阅读。', w: [349], note: '' },
  { id: 336, lv: 2, en: 'A positive attitude towards mistakes helps you learn much faster.', zh: '对错误的积极态度能帮你学得快得多。', w: [350], note: '' },
  { id: 337, lv: 2, en: 'Nobody can predict exactly how long it takes to master a language.', zh: '没人能准确预测掌握一门语言要多久。', w: [351], note: '' },
  { id: 338, lv: 2, en: 'Some learners prefer paper notebooks, while others like apps on their phones.', zh: '有些学习者更喜欢纸质笔记本，有些人则喜欢手机应用。', w: [352], note: 'prefer A to B / while 对比' },

  // ---------- Lv3 扩充（对应新增进阶词） ----------
  { id: 339, lv: 3, en: 'Do not abandon a learning method after only two or three days.', zh: '不要只用了两三天就放弃一种学习方法。', w: [353], note: '' },
  { id: 340, lv: 3, en: 'Abstract ideas are easier to remember when you attach them to a picture.', zh: '把抽象概念和画面联系起来会更容易记住。', w: [354], note: '' },
  { id: 341, lv: 3, en: 'Soft music often accompanies his reading late in the quiet evening.', zh: '深夜安静地阅读时，他常放着轻音乐。', w: [355], note: '' },
  { id: 342, lv: 3, en: 'A good dictionary gives accurate information about how a word is used.', zh: '好词典会准确提供单词用法的信息。', w: [356], note: '' },
  { id: 343, lv: 3, en: 'We must acknowledge that consistent review matters more than long study hours.', zh: '我们必须承认：持续复习比长时间学习更重要。', w: [357], note: '' },
  { id: 344, lv: 3, en: 'Twenty minutes a day is adequate for reviewing the words you just met.', zh: '每天二十分钟足以复习刚接触的单词。', w: [358], note: '' },
  { id: 345, lv: 3, en: 'You can adjust the difficulty of the exercises as your vocabulary grows.', zh: '随着词汇量增长，你可以调整练习难度。', w: [359], note: '' },
  { id: 346, lv: 3, en: 'Many teachers advocate reading aloud in the morning rather than late at night.', zh: '许多老师提倡早晨朗读，而不是深夜朗读。', w: [360], note: '' },
  { id: 347, lv: 3, en: 'Flashcards are a useful alternative to long lists of words with meanings.', zh: '单词卡是长串词义清单的有效替代品。', w: [361], note: 'an alternative to ……的替代方案' },
  { id: 348, lv: 3, en: 'The instructions were ambiguous, so half the class did the wrong task.', zh: '说明含糊不清，结果一半同学做错了任务。', w: [362], note: '' },
  { id: 349, lv: 3, en: 'Take a few minutes to analyze why you keep forgetting the same words.', zh: '花几分钟分析一下你为什么总忘同样的词。', w: [363], note: '' },
  { id: 350, lv: 3, en: 'Good learners anticipate the difficult parts before they start a new lesson.', zh: '优秀的学习者在开始新课前就预见到难点。', w: [364], note: '' },
  { id: 351, lv: 3, en: 'It soon became apparent that silent reading alone would not fix his pronunciation.', zh: '很快就明显看出，仅靠默读改不了他的发音。', w: [365], note: 'It became apparent that 显然' },
  { id: 352, lv: 3, en: 'Short stories have a wide appeal for learners who hate long textbooks.', zh: '短篇故事对讨厌长教材的学习者很有吸引力。', w: [366], note: '' },
  { id: 353, lv: 3, en: 'Choose materials at an appropriate level, or you will lose interest quickly.', zh: '选合适难度的材料，否则很快就会失去兴趣。', w: [367], note: '' },
  { id: 354, lv: 3, en: 'The school will approve the new reading plan before the term starts.', zh: '学校会在学期开始前批准新的阅读计划。', w: [368], note: '' },
  { id: 355, lv: 3, en: 'Teachers assess progress through short weekly tasks, not only through final exams.', zh: '老师通过每周小任务评估进步，而不只看期末考。', w: [369], note: '' },
  { id: 356, lv: 3, en: 'The teacher assigned each group a short article to prepare for Monday.', zh: '老师给每个小组布置了一篇短文，准备周一用。', w: [370], note: '' },
  { id: 357, lv: 3, en: 'Older students often assist younger ones with their listening practice after class.', zh: '高年级学生常在课后帮助低年级练听力。', w: [371], note: 'assist sb. with 协助某人' },
  { id: 358, lv: 3, en: 'Do not assume that a familiar word always keeps the same meaning.', zh: '别以为熟悉的词意思总是不变。', w: [372], note: '' },
  { id: 359, lv: 3, en: 'I can assure you that short daily practice really does make a difference.', zh: '我可以向你保证，每天短时练习确实有效。', w: [373], note: 'make a difference 起作用' },
  { id: 360, lv: 3, en: 'We attach great importance to the words that appear again and again.', zh: '我们非常重视反复出现的单词。', w: [374], note: 'attach importance to 重视' },
  { id: 361, lv: 3, en: 'He attributes his progress to ten minutes of reading every single morning.', zh: '他把进步归功于每天早上十分钟的阅读。', w: [375], note: 'attribute A to B 把A归因于B' },
  { id: 362, lv: 3, en: 'Good learners are aware of which words they still cannot use actively.', zh: '优秀的学习者清楚哪些词自己还不会主动使用。', w: [376], note: 'be aware of 意识到' },
  { id: 363, lv: 3, en: 'Children behave very differently when the lesson feels like a game.', zh: '当课堂像游戏时，孩子们的表现完全不同。', w: [377], note: '' },
  { id: 364, lv: 3, en: 'Try to read both sides so that personal bias does not shape your answer.', zh: '尽量两边都读，别让个人偏见影响你的答案。', w: [378], note: '' },
  { id: 365, lv: 3, en: 'The app can calculate how many words you should review the next day.', zh: '这款应用能算出你第二天该复习多少单词。', w: [379], note: '' },
  { id: 366, lv: 3, en: 'Our capacity to remember new words improves when we sleep well at night.', zh: '晚上睡得好，我们记生词的能力就会提升。', w: [380], note: 'capacity to do ……的能力' },
  { id: 367, lv: 3, en: 'Put each new word into a category, and review becomes much easier.', zh: '把每个生词归入一个类别，复习就容易多了。', w: [381], note: '' },
  { id: 368, lv: 3, en: 'Could you clarify the difference between these two very similar words?', zh: '你能说明这两个极为相似的词的区别吗？', w: [382], note: '' },
  { id: 369, lv: 3, en: 'A coherent answer is clearer than one full of long, difficult words.', zh: '连贯的回答比堆满生僻长词的回答更清晰。', w: [383], note: '' },
  { id: 370, lv: 3, en: 'Our class will collaborate with another school on a short reading project.', zh: '我们班将与另一所学校合作一个小型阅读项目。', w: [384], note: 'collaborate with 与……合作' },
  { id: 371, lv: 3, en: 'Nothing can compensate for the hundreds of hours of practice you skipped.', zh: '什么也弥补不了你跳过的数百小时练习。', w: [385], note: 'compensate for 弥补' },
  { id: 372, lv: 3, en: 'A competent learner knows when to stop and check a word in context.', zh: '合格的学习者知道何时停下来结合上下文查词。', w: [386], note: '' },
  { id: 373, lv: 3, en: 'This sentence looks complex, but the structure is actually quite simple.', zh: '这个句子看着复杂，结构其实相当简单。', w: [387], note: '' },
  { id: 374, lv: 3, en: 'All students must comply with the rules of the language laboratory.', zh: '所有学生都必须遵守语音室的规章。', w: [388], note: 'comply with 遵守' },
  { id: 375, lv: 3, en: 'There is often a conflict between what we plan and what we do.', zh: '我们计划的和实际做的之间常有冲突。', w: [389], note: '' },
  { id: 376, lv: 3, en: 'Be conscious of the small habits that quietly steal your study time.', zh: '留意那些悄悄偷走你学习时间的小习惯。', w: [390], note: 'be conscious of 意识到' },
  { id: 377, lv: 3, en: 'The class reached a consensus: ten minutes of review before bed, every night.', zh: '全班达成共识：每晚睡前复习十分钟。', w: [391], note: 'reach a consensus 达成共识' },
  { id: 378, lv: 3, en: 'He spent a considerable amount of time on just ten difficult words.', zh: '他在仅仅十个难词上就花了相当多的时间。', w: [392], note: '' },
  { id: 379, lv: 3, en: 'Real fluency does not consist of knowing words, but of using them.', zh: '真正的流利不在于认识词，而在于会用词。', w: [393], note: 'consist of 由……组成' },
  { id: 380, lv: 3, en: 'Constant review, even for five minutes, beats one long session each week.', zh: '哪怕只有五分钟的持续复习，也胜过每周一次的长复习。', w: [394], note: '' },
  { id: 381, lv: 3, en: 'These short daily tasks constitute the core of the whole programme.', zh: '这些每日小任务构成了整个项目的核心。', w: [395], note: '' },
  { id: 382, lv: 3, en: 'When in doubt, consult a dictionary instead of guessing from the context.', zh: '有疑问时查词典，而不是凭上下文猜。', w: [396], note: '' },
  { id: 383, lv: 3, en: 'Children consume far more short videos than books these days, unfortunately.', zh: '如今孩子们消费的短视频远多于书籍。', w: [397], note: '' },
  { id: 384, lv: 3, en: 'Contemporary writers use short sentences that are perfect for language learners.', zh: '当代作家使用的短句非常适合语言学习者。', w: [398], note: '' },
  { id: 385, lv: 3, en: 'The two reports contradict each other, so we need a third source.', zh: '两份报告相互矛盾，所以我们需要第三个来源。', w: [399], note: '' },
  { id: 386, lv: 3, en: 'In contrast to last term, he now reviews his notes every evening.', zh: '与上学期相反，他现在每晚都复习笔记。', w: [400], note: 'in contrast to 与……相反' },
  { id: 387, lv: 3, en: 'There was some controversy about whether phones should be allowed in class.', zh: '关于课堂上是否该允许用手机存在一些争议。', w: [401], note: '' },
  { id: 388, lv: 3, en: 'A short sentence can convey an idea more clearly than a long one.', zh: '短句比长句更能清晰地传达想法。', w: [402], note: '' },
  { id: 389, lv: 3, en: 'The two classes agreed to cooperate on a shared word list this term.', zh: '两个班同意本学期共用一份单词表来合作。', w: [403], note: 'cooperate on 在……上合作' },
  { id: 390, lv: 3, en: 'One teacher will coordinate the reading schedule for all the first-year groups.', zh: '一位老师会统筹所有一年级班级的阅读安排。', w: [404], note: '' },
  { id: 391, lv: 3, en: 'Reviewing on the same day is crucial for keeping a new word alive.', zh: '当天复习对让生词"活下来"至关重要。', w: [405], note: '' },
  { id: 392, lv: 3, en: 'Stay curious about why a word is used in this particular situation.', zh: '对为什么在此情境下用这个词保持好奇。', w: [406], note: 'be curious about 对……好奇' },
  { id: 393, lv: 3, en: 'His interest in reading showed a sharp decline after the long holiday.', zh: '长假之后，他对阅读的兴趣明显下降。', w: [407], note: '' },
  { id: 394, lv: 3, en: 'She dedicates the first hour of every day to reading and review.', zh: '她每天把第一个小时用于阅读和复习。', w: [408], note: 'dedicate ... to ...' },
  { id: 395, lv: 3, en: 'Set a definite time for review, or the day will simply disappear.', zh: '给复习定个明确时间，否则一天就这么没了。', w: [409], note: '' },
  { id: 396, lv: 3, en: 'Reading aloud slowly is a deliberate way to train both ear and mouth.', zh: '慢慢朗读是一种同时训练耳朵和嘴巴的有意做法。', w: [410], note: '' },
  { id: 397, lv: 3, en: 'These examples demonstrate how the same word changes meaning across contexts.', zh: '这些例子说明同一个词在不同语境中如何改变含义。', w: [411], note: '' },
  { id: 398, lv: 3, en: 'Many English words derive from Latin, which makes guessing a little easier.', zh: '许多英语单词源自拉丁语，这让猜词容易一些。', w: [412], note: 'derive from 源于' },
  { id: 399, lv: 3, en: 'The app can detect the words you hesitate on for more than three seconds.', zh: '这款应用能识别你迟疑超过三秒的单词。', w: [413], note: '' },
  { id: 400, lv: 3, en: 'Sleeping badly will diminish your ability to remember anything new.', zh: '睡不好会削弱你记住新东西的能力。', w: [414], note: '' },
  { id: 401, lv: 3, en: 'Learning a language requires discipline more than it requires natural talent.', zh: '学语言需要的自律多于天赋。', w: [415], note: '' },
  { id: 402, lv: 3, en: 'British and American English have distinct spellings for the same everyday words.', zh: '英式与美式英语对同样的日常词有不同拼写。', w: [416], note: '' },
  { id: 403, lv: 3, en: 'The teacher distributes a short word list at the start of each week.', zh: '老师每周初分发一份简短的单词表。', w: [417], note: '' },
  { id: 404, lv: 3, en: 'Reading diverse materials exposes you to the same word in many contexts.', zh: '阅读多样材料能让你在许多语境中遇到同一个词。', w: [418], note: '' },
  { id: 405, lv: 3, en: 'Do not let one difficult word dominate your attention during the first reading.', zh: '第一次阅读时别让一个难词占据你全部注意力。', w: [419], note: '' },
  { id: 406, lv: 3, en: 'Children are eager to share the stories they read with anyone nearby.', zh: '孩子们急切地想和身边任何人分享读过的故事。', w: [420], note: 'be eager to do 渴望做' },
  { id: 407, lv: 3, en: 'You do not need an elaborate plan; a simple daily habit is enough.', zh: '你不需要复杂的计划，一个简单的每日习惯就够了。', w: [421], note: '' },
  { id: 408, lv: 3, en: 'New problems usually emerge only after you start using the words yourself.', zh: '新问题往往在你自己开始使用这些词之后才出现。', w: [422], note: '' },
  { id: 409, lv: 3, en: 'Good teachers emphasize using a word, not just recognising it on paper.', zh: '好老师强调运用单词，而不只是在纸上认出它。', w: [423], note: '' },
  { id: 410, lv: 3, en: 'Short daily reviews enable you to meet each word again and again.', zh: '每天短时复习让你能反复遇到每个单词。', w: [424], note: 'enable sb. to do 使某人能够' },
  { id: 411, lv: 3, en: 'You will encounter the same words again if you keep reading widely.', zh: '只要坚持广泛阅读，你会再次遇到同样的词。', w: [425], note: '' },
  { id: 412, lv: 3, en: 'Reading aloud every morning can enhance both memory and speaking confidence.', zh: '每天早上朗读能增强记忆力和口语自信。', w: [426], note: '' },
  { id: 413, lv: 3, en: 'He has an enormous collection of short stories on his small bookshelf.', zh: '他的小书架上收藏了大量短篇小说。', w: [427], note: '' },
  { id: 414, lv: 3, en: 'Ten minutes of review is not equivalent to ten minutes of real use.', zh: '十分钟复习并不等于十分钟的真正运用。', w: [428], note: 'be equivalent to 等同于' },
  { id: 415, lv: 3, en: 'A small daily habit is essential if you want steady, quiet progress.', zh: '想要平稳踏实的进步，每日小习惯必不可少。', w: [429], note: '' },
  { id: 416, lv: 3, en: 'Try to establish one reading routine before adding any new learning tools.', zh: '在增加新学习工具前，先建立一个阅读习惯。', w: [430], note: '' },
  { id: 417, lv: 3, en: 'Evaluate your progress every two weeks, not after every single lesson.', zh: '每两周评估一次进步，而不是每节课后都评估。', w: [431], note: '' },
  { id: 418, lv: 3, en: 'It is evident that short reviews beat long cramming sessions before exams.', zh: '显然，短时复习胜过考前长时间突击。', w: [432], note: '' },
  { id: 419, lv: 3, en: 'The number of new words should not exceed twenty in a single day.', zh: '一天的新词数量不应超过二十个。', w: [433], note: '' },
  { id: 420, lv: 3, en: 'A good word list excludes words you will almost never meet in real life.', zh: '好的单词表会剔除你在现实中几乎不会遇到的词。', w: [434], note: '' },
  { id: 421, lv: 3, en: 'Give explicit instructions, or students will guess what the task means.', zh: '给出明确的指示，否则学生只能猜任务是什么。', w: [435], note: '' },
  { id: 422, lv: 3, en: 'Learners should exploit every short break to review a few old words.', zh: '学习者应利用每一个短暂休息复习几个旧词。', w: [436], note: '' },
  { id: 423, lv: 3, en: 'External pressure fades, but a habit you built yourself stays with you.', zh: '外部压力会消退，但你自己养成的习惯会留下。', w: [437], note: '' },
  { id: 424, lv: 3, en: 'Twenty new words a day is feasible for most busy working adults.', zh: '对多数忙碌的上班族来说，每天二十个生词是可行的。', w: [438], note: '' },
  { id: 425, lv: 3, en: 'Your motivation will fluctuate, so build habits that survive the low days.', zh: '你的动力会起伏，所以要养成能挺过低谷的习惯。', w: [439], note: '' },
  { id: 426, lv: 3, en: 'Take time to formulate your own sentence instead of copying the example.', zh: '花时间自己造个句子，而不是照抄例句。', w: [440], note: '' },
  { id: 427, lv: 3, en: 'There is one fundamental rule: meet the same word in different sentences.', zh: '有一条基本规则：在不同句子里遇到同一个词。', w: [441], note: '' },
  { id: 428, lv: 3, en: 'Reading widely will generate far more questions than any classroom ever could.', zh: '广泛阅读产生的问题远多于任何课堂。', w: [442], note: '' },
  { id: 429, lv: 3, en: 'Progress in a language is gradual, and most of it is invisible.', zh: '语言的进步是渐进的，而且大多看不见。', w: [443], note: '' },
  { id: 430, lv: 3, en: 'Our hypothesis was simple: shorter reviews lead to longer-lasting memory.', zh: '我们的假设很简单：复习越短时，记忆越持久。', w: [444], note: '' },
  { id: 431, lv: 3, en: 'The two sentences look identical, yet only one sounds natural to natives.', zh: '两句看着一模一样，但只有一句对母语者自然。', w: [445], note: '' },
  { id: 432, lv: 3, en: 'It is easier to implement a small plan than to design a perfect one.', zh: '执行一个小计划比设计一个完美计划容易。', w: [446], note: '' },
  { id: 433, lv: 3, en: 'Do not impose a heavy schedule on yourself during the first two weeks.', zh: '头两周别给自己强加过重的计划。', w: [447], note: 'impose ... on ...' },
  { id: 434, lv: 3, en: 'A small reward is a strong incentive to keep the habit going.', zh: '小小的奖励是维持习惯的强大动力。', w: [448], note: '' },
  { id: 435, lv: 3, en: 'Try to incorporate the new words into your next short writing task.', zh: '试着把生词用到你下一篇小写作里。', w: [449], note: 'incorporate ... into ...' },
  { id: 436, lv: 3, en: 'From his tone we can infer that he is not fully convinced yet.', zh: '从他的语气可以推断他还没有完全被说服。', w: [450], note: '' },
  { id: 437, lv: 3, en: 'There is an inherent difficulty in words that have no single Chinese equivalent.', zh: '没有唯一中文对应词的单词存在固有的难度。', w: [451, 428], note: '' },
  { id: 438, lv: 3, en: 'Fear of mistakes can inhibit even a learner who knows the words well.', zh: '对错误的恐惧会抑制即便词汇熟练的学习者。', w: [452], note: '' },
  { id: 439, lv: 3, en: 'The teacher will initiate a ten-minute reading session at the start of class.', zh: '老师会在课开始时发起十分钟的阅读环节。', w: [453], note: '' },
  { id: 440, lv: 3, en: 'Old notes often give you an insight you missed during the first reading.', zh: '旧笔记常给你初读时错过的洞见。', w: [454], note: '' },
  { id: 441, lv: 3, en: 'A short story can inspire a learner far more than a long lecture.', zh: '一篇短故事对学习者的激励远超过一场长讲座。', w: [455], note: '' },
  { id: 442, lv: 3, en: 'Review is an integral part of learning, not something extra at the end.', zh: '复习是学习的组成部分，而不是最后的附加项。', w: [456], note: '' },
  { id: 443, lv: 3, en: 'Intense study for one week rarely beats calm study for three months.', zh: '高强度学一周很难胜过平静地学三个月。', w: [457], note: '' },
  { id: 444, lv: 3, en: 'Learners often interpret a new word through the grammar of their first language.', zh: '学习者常通过母语的语法来理解新词。', w: [458], note: '' },
  { id: 445, lv: 3, en: 'Good teachers intervene only when a mistake blocks the whole meaning.', zh: '好老师只在错误阻碍整体意思时才介入。', w: [459], note: '' },
  { id: 446, lv: 3, en: 'It pays to investigate why one method works for you and another does not.', zh: '弄清为什么一种方法对你有效而另一种无效是值得的。', w: [460], note: '' },
  { id: 447, lv: 3, en: 'Nothing can justify spending hours on words you will never actually use.', zh: '花几小时在你永远不会用的词上，无法被证明是合理的。', w: [461], note: '' },
  { id: 448, lv: 3, en: 'New legislation on education will take effect at the start of next year.', zh: '新的教育法规将于明年初生效。', w: [462], note: 'take effect 生效' },
  { id: 449, lv: 3, en: 'His writing became much more mature after two years of daily reading.', zh: '两年每日阅读之后，他的写作成熟多了。', w: [463], note: '' },
  { id: 450, lv: 3, en: 'Spaced review is the mechanism behind almost every successful learning app.', zh: '间隔复习几乎是每个成功学习应用背后的机制。', w: [464], note: '' },
  { id: 451, lv: 3, en: 'Short reviews help minimize the time you spend re-learning forgotten words.', zh: '短时复习有助于把重学遗忘词的时间降到最低。', w: [465], note: '' },
  { id: 452, lv: 3, en: 'A moderate amount of new words each day is better than a huge list.', zh: '每天适量的生词好过一大张清单。', w: [466], note: '' },
  { id: 453, lv: 3, en: 'Feel free to modify the plan whenever it stops fitting your real life.', zh: '一旦计划不再适合你的真实生活，随时修改。', w: [467], note: '' },
  { id: 454, lv: 3, en: 'Parents and teachers should nurture a child\'s interest in reading for pleasure.', zh: '家长和老师应培养孩子为乐趣而阅读的兴趣。', w: [468], note: '' },
  { id: 455, lv: 3, en: 'The notion that adults cannot learn languages is simply wrong and harmful.', zh: '成年人学不了语言这一观念根本错误且有害。', w: [469], note: '' },
  { id: 456, lv: 3, en: 'Set one clear objective for each week, such as finishing one short book.', zh: '每周设一个明确目标，比如读完一本小书。', w: [470], note: '' },
  { id: 457, lv: 3, en: 'Lack of time is a real obstacle, but lack of a plan is worse.', zh: '缺少时间是真实障碍，但缺少计划更糟。', w: [471], note: '' },
  { id: 458, lv: 3, en: 'This course is oriented towards learners who want to speak, not just read.', zh: '本课程面向想开口、而不只是阅读的学习者。', w: [472], note: 'be oriented towards 面向' },
  { id: 459, lv: 3, en: 'If you persist with ten minutes a day, the results will surprise you.', zh: '如果你坚持每天十分钟，结果会让你惊喜。', w: [473], note: 'persist with 坚持' },
  { id: 460, lv: 3, en: 'Keep a precise record of the words you keep forgetting again and again.', zh: '精确记录你反复遗忘的单词。', w: [474], note: '' },
  { id: 461, lv: 3, en: 'We presume that most learners already know these common function words.', zh: '我们假定多数学习者已经认识这些常见功能词。', w: [475], note: '' },
  { id: 462, lv: 3, en: 'In the end, patience and steady habits prevail over sudden bursts of effort.', zh: '最终，耐心与稳定习惯会胜过突然的努力爆发。', w: [476], note: 'prevail over 胜过' },
  { id: 463, lv: 3, en: 'She plays a prominent role in the school reading club every week.', zh: '她每周在学校读书俱乐部里起着重要作用。', w: [477], note: 'play a prominent role in' },
  { id: 464, lv: 3, en: 'Schools should promote reading for pleasure instead of reading only for tests.', zh: '学校应推广为乐趣而读，而非只为考试而读。', w: [478], note: '' },
  { id: 465, lv: 3, en: 'Many adults pursue English for travel, work, or simply personal satisfaction.', zh: '许多成年人学英语是为了旅行、工作，或只是个人满足。', w: [479], note: '' },
  { id: 466, lv: 3, en: 'A rational plan fits your real schedule instead of an ideal one.', zh: '理性的计划应适合你的真实日程，而非理想日程。', w: [480], note: '' },
  { id: 467, lv: 3, en: 'Short quizzes reinforce what you read the night before, and nothing else.', zh: '小测验强化的是你前一天晚上读过的内容。', w: [481], note: '' },
  { id: 468, lv: 3, en: 'Choose materials that are relevant to your work, your studies or your hobbies.', zh: '选与你的工作、学业或爱好相关的材料。', w: [482], note: 'be relevant to 与……相关' },
  { id: 469, lv: 3, en: 'A reliable method is one you can still follow on your worst day.', zh: '可靠的方法是你状态最差时仍能执行的方法。', w: [483], note: '' },
  { id: 470, lv: 3, en: 'Many learners are reluctant to speak until their pronunciation feels perfect.', zh: '许多学习者不愿开口，除非发音感觉完美。', w: [484], note: 'be reluctant to do 不愿做' },
  { id: 471, lv: 3, en: 'Do not restrict your reading to textbooks; short news and stories count.', zh: '别把阅读局限在教材上；短新闻和故事也算。', w: [485], note: 'restrict ... to ...' },
  { id: 472, lv: 3, en: 'Reading widely will reveal how often the same words quietly repeat.', zh: '广泛阅读会揭示同样的词悄悄重复得有多频繁。', w: [486], note: '' },
  { id: 473, lv: 3, en: 'A rigid plan often breaks during the first busy week of the month.', zh: '僵硬的计划常在每月第一个忙碌的周就崩了。', w: [487], note: '' },
  { id: 474, lv: 3, en: 'Imagine this scenario: ten minutes of reading before every single meal.', zh: '想象这个场景：每顿饭前读十分钟。', w: [488], note: '' },
  { id: 475, lv: 3, en: 'The new reading scheme starts with ten words and grows slowly from there.', zh: '新的阅读计划从十个单词开始，再慢慢增加。', w: [489], note: '' },
  { id: 476, lv: 3, en: 'Learn words in a sequence that follows the topics of your daily life.', zh: '按与你日常生活主题相关的顺序来学单词。', w: [490], note: '' },
  { id: 477, lv: 3, en: 'There has been a clear shift from memorising words to using them.', zh: '从背单词到用单词，已经有了明显的转变。', w: [491], note: '' },
  { id: 478, lv: 3, en: 'Please specify how many words you want to review in each session.', zh: '请说明你每次想复习多少个单词。', w: [492], note: '' },
  { id: 479, lv: 3, en: 'A stable routine matters far more than the perfect learning app.', zh: '稳定的习惯远比完美的学习应用重要。', w: [493], note: '' },
  { id: 480, lv: 3, en: 'Short questions stimulate thinking much better than long silent reading.', zh: '简短的提问比长时间默读更能激发思考。', w: [494], note: '' },
  { id: 481, lv: 3, en: 'You must submit your short summary before the end of the class.', zh: '你必须在下课前提交简短的总结。', w: [495], note: '' },
  { id: 482, lv: 3, en: 'Twenty minutes of daily reading is sufficient if you do it every day.', zh: '只要每天坚持，每天二十分钟阅读就足够了。', w: [496], note: '' },

  // ---------- Lv4 扩充（对应新增冲刺词） ----------
  { id: 483, lv: 4, en: 'The school decided to abolish the old rule about silent morning reading.', zh: '学校决定废除关于晨读必须默读的旧规定。', w: [497], note: '' },
  { id: 484, lv: 4, en: 'Young children absorb new words far faster than most adults ever do.', zh: '幼儿吸收新词的速度远快于多数成年人。', w: [498], note: '' },
  { id: 485, lv: 4, en: 'This short course can accommodate learners of very different levels and ages.', zh: '这门短课能容纳水平和年龄差异很大的学习者。', w: [499], note: '' },
  { id: 486, lv: 4, en: 'Small daily reviews accumulate into a vocabulary that surprises you after a year.', zh: '每天的小复习累积成一年后让你惊喜的词汇量。', w: [500], note: '' },
  { id: 487, lv: 4, en: 'All members must adhere to the simple rules of the reading club.', zh: '所有成员都必须遵守读书俱乐部的简单规则。', w: [501], note: 'adhere to 遵守' },
  { id: 488, lv: 4, en: 'Try to allocate twenty quiet minutes to review before the day gets busy.', zh: '在一天变忙之前，尽量拨出安静的二十分钟复习。', w: [502], note: 'allocate ... to ...' },
  { id: 489, lv: 4, en: 'Reading aloud can amplify the small differences between similar English sounds.', zh: '朗读能放大相似英语发音之间的细微差别。', w: [503], note: '' },
  { id: 490, lv: 4, en: 'A simple analogy helps: words are bricks, and sentences are the house.', zh: '一个简单的类比有帮助：单词是砖，句子是房子。', w: [504], note: '' },
  { id: 491, lv: 4, en: 'Choosing words in an arbitrary order makes review much harder than it should be.', zh: '以任意顺序选词会让复习变得比应有的困难。', w: [505], note: '' },
  { id: 492, lv: 4, en: 'It takes practice to articulate an idea clearly in a second language.', zh: '用第二语言清晰表达想法需要练习。', w: [506], note: '' },
  { id: 493, lv: 4, en: 'The teacher tried to ascertain why some students stopped reviewing entirely.', zh: '老师试图查明为什么有些学生完全停止了复习。', w: [507], note: '' },
  { id: 494, lv: 4, en: 'I would assert that daily practice matters more than any natural talent.', zh: '我敢断言每日练习比任何天赋都重要。', w: [508], note: '' },
  { id: 495, lv: 4, en: 'Reading authentic materials is harder at first, but far more rewarding later.', zh: '读真实材料一开始更难，但之后回报大得多。', w: [509], note: '' },
  { id: 496, lv: 4, en: 'Short successes early on will bolster your confidence for the difficult months.', zh: '早期的一些小成就会增强你面对困难月份的信心。', w: [510], note: '' },
  { id: 497, lv: 4, en: 'In the modern world, fluent English has almost become a valuable commodity.', zh: '在当今世界，流利的英语几乎成了一种有价值的商品。', w: [511], note: '' },
  { id: 498, lv: 4, en: 'Make sure the new app is compatible with the old notes you already keep.', zh: '确保新应用与你已有的旧笔记兼容。', w: [512], note: 'be compatible with 与……兼容' },
  { id: 499, lv: 4, en: 'A compelling story keeps learners reading long after the lesson has ended.', zh: '引人入胜的故事让学习者在课后很久仍继续阅读。', w: [513], note: '' },
  { id: 500, lv: 4, en: 'As a small concession, the teacher allowed us to use dictionaries this time.', zh: '作为小小的让步，老师这次允许我们用词典。', w: [514], note: '' },
  { id: 501, lv: 4, en: 'Write concise notes, because long ones are rarely read a second time.', zh: '笔记要写得简明，因为长的很少会被再读一遍。', w: [515], note: '' },
  { id: 502, lv: 4, en: 'A quiet corner and warm light are conducive to long, calm reading.', zh: '安静的角落和温暖的灯光有助于长时间平静阅读。', w: [516], note: 'be conducive to 有助于' },
  { id: 503, lv: 4, en: 'A heavy workload constrains even the most motivated learners in this programme.', zh: '繁重的课业负担限制了这个项目里最有动力的学习者。', w: [517], note: '' },
  { id: 504, lv: 4, en: 'Take a few minutes to contemplate which habit you should change first.', zh: '花几分钟思考你该先改变哪个习惯。', w: [518], note: '' },
  { id: 505, lv: 4, en: 'Our weekend plan is contingent on whether the weather stays dry and warm.', zh: '我们的周末计划取决于天气是否保持干爽温暖。', w: [519], note: 'be contingent on 视……而定' },
  { id: 506, lv: 4, en: 'Studies correlate regular short review with much longer-lasting word memory.', zh: '研究把规律的短时复习与更持久的单词记忆联系起来。', w: [520], note: 'correlate A with B' },
  { id: 507, lv: 4, en: 'The cumulative effect of ten minutes a day is easy to underestimate.', zh: '每天十分钟的累积效果很容易被低估。', w: [521, 54], note: '' },
  { id: 508, lv: 4, en: 'You need to curb the habit of checking your phone during every break.', zh: '你得改掉每个休息时间都看手机的习惯。', w: [522], note: '' },
  { id: 509, lv: 4, en: 'The school plans to decentralize the library so every classroom has books.', zh: '学校计划把图书馆分散，让每个教室都有书。', w: [523], note: '' },
  { id: 510, lv: 4, en: 'His vocabulary is deficient in the small everyday words native speakers use most.', zh: '他的词汇在母语者最常用的日常小词上有所欠缺。', w: [524], note: '' },
  { id: 511, lv: 4, en: 'Reading only headlines will slowly degrade your patience for longer texts.', zh: '只读标题会慢慢削弱你对长文本的耐心。', w: [525], note: '' },
  { id: 512, lv: 4, en: 'Old paper dictionaries depreciate quickly once a better app appears online.', zh: '一旦出现更好的应用，旧纸质词典很快就贬值。', w: [526], note: '' },
  { id: 513, lv: 4, en: 'Harsh criticism can deter a shy learner from ever speaking again.', zh: '严厉的批评会吓退害羞的学习者，让他再也不开口。', w: [527], note: 'deter sb. from doing 阻止某人做' },
  { id: 514, lv: 4, en: 'A few spelling mistakes do not detract from the value of your answer.', zh: '几个拼写错误无损于你答案的价值。', w: [528], note: 'detract from 减损' },
  { id: 515, lv: 4, en: 'Trained readers can discern the tone of a sentence within a few seconds.', zh: '训练有素的读者几秒内就能辨出句子的语气。', w: [529], note: '' },
  { id: 516, lv: 4, en: 'One careless error should not discredit months of careful, honest work.', zh: '一个粗心的错误不应让数月认真诚实的工作蒙受质疑。', w: [530], note: '' },
  { id: 517, lv: 4, en: 'There is a wide disparity between the words we know and the words we use.', zh: '我们认识的词和会用的词之间存在很大差距。', w: [531], note: '' },
  { id: 518, lv: 4, en: 'The internet can disseminate a useful learning method within a single week.', zh: '互联网能在一周之内传播开一种有用的学习方法。', w: [532], note: '' },
  { id: 519, lv: 4, en: 'British and American usage diverge most in small everyday words and spellings.', zh: '英式与美式用法差异最大的地方是日常小词和拼写。', w: [533], note: '' },
  { id: 520, lv: 4, en: 'Try to diversify your reading so the same words appear in new places.', zh: '试着让阅读多样化，让同样的词出现在新场合。', w: [534], note: '' },
  { id: 521, lv: 4, en: 'Drastic changes to your schedule rarely survive the first busy working week.', zh: '对日程的剧烈改动很少能挺过第一个忙碌的工作周。', w: [535], note: '' },
  { id: 522, lv: 4, en: 'Do not simply duplicate the example sentence; change one part of it.', zh: '不要照抄例句，改动其中一部分。', w: [536], note: '' },
  { id: 523, lv: 4, en: 'Open questions elicit far more English from students than simple yes-or-no ones.', zh: '开放式问题比简单是非题更能引出学生的英语。', w: [537], note: '' },
  { id: 524, lv: 4, en: 'Young learners often emulate the speaking style of a teacher they admire.', zh: '年轻学习者常模仿自己尊敬的老师的说话风格。', w: [538], note: '' },
  { id: 525, lv: 4, en: 'Several teachers endorsed the new reading plan after trying it for a month.', zh: '试用一个月后，几位老师都支持新的阅读计划。', w: [539], note: '' },
  { id: 526, lv: 4, en: 'Good stories endow ordinary words with feelings you will not easily forget.', zh: '好故事赋予普通单词你不易忘记的情感。', w: [540], note: 'endow ... with ...' },
  { id: 527, lv: 4, en: 'No method can eradicate the need to meet a word again and again.', zh: '没有任何方法能消除反复遇到一个词的必要性。', w: [541], note: '' },
  { id: 528, lv: 4, en: 'Long gaps without reading will erode even a strong vocabulary quite quickly.', zh: '长时间不阅读会相当快地侵蚀哪怕很强的词汇量。', w: [542], note: '' },
  { id: 529, lv: 4, en: 'Small gaps in understanding can escalate into real confusion within a few lessons.', zh: '理解上的小缺口会在几节课内升级成真正的困惑。', w: [543], note: '' },
  { id: 530, lv: 4, en: 'Cramming before an exam only exacerbates the fear of long English texts.', zh: '考前突击只会加剧对长篇英语文章的恐惧。', w: [544], note: '' },
  { id: 531, lv: 4, en: 'Her exemplary notes became the model for the whole class that term.', zh: '她那学期堪称典范的笔记成了全班的模板。', w: [545], note: '' },
  { id: 532, lv: 4, en: 'Clear goals can expedite your progress more than any new learning tool.', zh: '清晰的目标比任何新学习工具都更能加快你的进步。', w: [546], note: '' },
  { id: 533, lv: 4, en: 'Do not extrapolate your first week of progress across the whole year.', zh: '不要用第一周的进步去推断整年的进展。', w: [547], note: '' },
  { id: 534, lv: 4, en: 'Schools should foster a habit of reading before they test any vocabulary.', zh: '学校应先培养阅读习惯，再去测词汇。', w: [548], note: '' },
  { id: 535, lv: 4, en: 'A frugal learner builds a vocabulary from free materials found everywhere.', zh: '节俭的学习者用随处可见的免费材料积累词汇。', w: [549], note: '' },
  { id: 536, lv: 4, en: 'One short success can galvanize a class that has lost all motivation.', zh: '一次小小的成功能激励已经完全失去动力的班级。', w: [550], note: '' },
  { id: 537, lv: 4, en: 'Noise and notifications hamper deep reading more than most learners realise.', zh: '噪音和通知对深度阅读的阻碍超出多数学习者认知。', w: [551], note: '' },
  { id: 538, lv: 4, en: 'Skilled readers harness context instead of running to a dictionary every time.', zh: '熟练的读者利用上下文，而不是每次都去查词典。', w: [552], note: '' },
  { id: 539, lv: 4, en: 'Perfect pronunciation should never hinder you from speaking to real people.', zh: '完美的发音绝不该妨碍你与真实的人交谈。', w: [553], note: 'hinder sb. from doing 妨碍某人做' },
  { id: 540, lv: 4, en: 'The class is fairly homogeneous, so the teacher can move at a steady pace.', zh: '这个班水平相当齐整，老师可以按稳定节奏推进。', w: [554], note: '' },
  { id: 541, lv: 4, en: 'The results of the speaking test are imminent, so review today and tomorrow.', zh: '口语考试结果即将公布，所以今明两天要复习。', w: [555], note: '' },
  { id: 542, lv: 4, en: 'Reading in a noisy room will impair your memory for new words.', zh: '在嘈杂房间阅读会损害你对生词的记忆。', w: [556], note: '' },
  { id: 543, lv: 4, en: 'Since its inception, the club has helped more than five hundred learners.', zh: '自创立以来，该俱乐部已帮助了五百多名学习者。', w: [557], note: 'since its inception 自创立以来' },
  { id: 544, lv: 4, en: 'Good teachers instill a love of reading long before they teach grammar.', zh: '好老师在教语法之前很久就灌输了对阅读的热爱。', w: [558], note: '' },
  { id: 545, lv: 4, en: 'Confidence is an intangible gain that no word list can ever give you.', zh: '自信是任何单词表都给不了的无形收获。', w: [559], note: '' },
  { id: 546, lv: 4, en: 'English spelling follows intricate rules that even native learners find confusing.', zh: '英语拼写遵循错综复杂的规则，连母语学习者都觉得困惑。', w: [560], note: '' },
  { id: 547, lv: 4, en: 'Curiosity is an intrinsic part of learning that no app can replace.', zh: '好奇心是学习中无法被应用替代的内在部分。', w: [561], note: '' },
  { id: 548, lv: 4, en: 'Teachers are often inundated with questions after a difficult reading lesson.', zh: '一节难的阅读课后，老师常被问题淹没。', w: [562], note: '' },
  { id: 549, lv: 4, en: 'One clear counterexample can invalidate a rule you believed for years.', zh: '一个明确的反例就能推翻你信奉多年的规则。', w: [563], note: '' },
  { id: 550, lv: 4, en: 'Adult learners need latitude to choose materials that fit their own interests.', zh: '成人学习者需要选择符合自己兴趣的材料的自由度。', w: [564], note: '' },
  { id: 551, lv: 4, en: 'Translation can be a lucrative skill for people who read widely in English.', zh: '对广泛阅读英语的人来说，翻译可以是赚钱的技能。', w: [565], note: '' },
  { id: 552, lv: 4, en: 'One bad experience can magnify a small fear into a lasting block.', zh: '一次糟糕的经历会把小小的恐惧放大成持久的障碍。', w: [566], note: '' },
  { id: 553, lv: 4, en: 'After the first month, each extra hour of study brings only marginal gains.', zh: '第一个月后，每多学一小时带来的收益都变得很小。', w: [567], note: '' },
  { id: 554, lv: 4, en: 'Regular short breaks mitigate the tiredness of a long evening study session.', zh: '规律的短暂休息能缓解漫长晚间学习的疲劳。', w: [568], note: '' },
  { id: 555, lv: 4, en: 'The club managed to mobilize volunteers for the reading programme in two weeks.', zh: '俱乐部两周内就为阅读项目动员到了志愿者。', w: [569], note: '' },
  { id: 556, lv: 4, en: 'The difference between these two methods is negligible for most busy learners.', zh: '对多数忙碌的学习者来说，这两种方法的差别微乎其微。', w: [570], note: '' },
  { id: 557, lv: 4, en: 'Some textbook expressions are already obsolete and sound strange to native speakers.', zh: '有些教材用语已经过时，在母语者听来很奇怪。', w: [571], note: '' },
  { id: 558, lv: 4, en: 'Copying long word lists by hand is an onerous task with little reward.', zh: '手抄长单词表是件繁重而回报甚微的事。', w: [572], note: '' },
  { id: 559, lv: 4, en: 'Twenty minutes a day seems to be the optimal length for most reviews.', zh: '对多数复习来说，每天二十分钟似乎是最佳时长。', w: [573], note: '' },
  { id: 560, lv: 4, en: 'This app represents a new paradigm: learning words through stories, not lists.', zh: '这款应用代表一种新范式：通过故事而非清单学单词。', w: [574], note: '' },
  { id: 561, lv: 4, en: 'English words from French permeate almost every formal document you will read.', zh: '源自法语的英语词几乎渗透进你会读到的每份正式文件。', w: [575], note: '' },
  { id: 562, lv: 4, en: 'These notes pertain to the reading task we discussed in the last lesson.', zh: '这些笔记涉及我们上节课讨论的阅读任务。', w: [576], note: 'pertain to 关于；涉及' },
  { id: 563, lv: 4, en: 'Guessing from context sounds plausible, but it often leads to the wrong meaning.', zh: '凭上下文猜测看似合理，却常导致错误的意思。', w: [577], note: '' },
  { id: 564, lv: 4, en: 'One careless comment can precipitate an argument that nobody actually wanted.', zh: '一句无心的话可能引发一场没人想要的争论。', w: [578], note: '' },
  { id: 565, lv: 4, en: 'A heavy timetable should not preclude ten minutes of quiet daily reading.', zh: '繁重的课表不该排除每天十分钟的安静阅读。', w: [579], note: '' },
  { id: 566, lv: 4, en: 'Short stories are the predominant reading material in most beginner classrooms.', zh: '短篇故事是多数入门课堂上占主导地位的阅读材料。', w: [580], note: '' },
  { id: 567, lv: 4, en: 'The whole method rests on one premise: words must be met repeatedly.', zh: '整个方法建立在一个前提上：单词必须被反复遇到。', w: [581], note: '' },
  { id: 568, lv: 4, en: 'Learning words in isolation is still prevalent despite years of better advice.', zh: '尽管多年来的建议更好，孤立背单词仍然普遍。', w: [582], note: '' },
  { id: 569, lv: 4, en: 'She has long been a proponent of reading aloud in every language class.', zh: '她一直是每节语言课都要朗读的倡导者。', w: [583], note: '' },
  { id: 570, lv: 4, en: 'Social media can propagate a poor translation faster than any dictionary can correct it.', zh: '社交媒体传播糟糕译文的速度快过任何词典的纠正。', w: [584], note: '' },
  { id: 571, lv: 4, en: 'It is prudent to review the old words before adding twenty new ones.', zh: '在增加二十个新词之前先复习旧词是明智的。', w: [585], note: '' },
  { id: 572, lv: 4, en: 'A calm answer can quell the anxiety that builds before a speaking test.', zh: '冷静的回答能平息口语考试前积聚的焦虑。', w: [586], note: '' },
  { id: 573, lv: 4, en: 'Without review, even well-known words slowly recede from active memory.', zh: '不复习的话，即便熟悉的词也会慢慢从主动记忆中退去。', w: [587], note: '' },
  { id: 574, lv: 4, en: 'Good conversation partners reciprocate by correcting you gently, not harshly.', zh: '好的对话伙伴会以温和而非严厉的纠正作为回报。', w: [588], note: '' },
  { id: 575, lv: 4, en: 'Take time to rectify the mistakes you make most often in writing.', zh: '花时间纠正你在写作中最常犯的错误。', w: [589], note: '' },
  { id: 576, lv: 4, en: 'One clear example is enough to refute the claim that adults cannot learn.', zh: '一个清晰的例子就足以驳斥成年人学不会的说法。', w: [590], note: '' },
  { id: 577, lv: 4, en: 'The school decided to reinstate the morning reading session after many requests.', zh: '在众多请求下，学校决定恢复晨读环节。', w: [591], note: '' },
  { id: 578, lv: 4, en: 'Few learners willingly relinquish the notes they spent months building by hand.', zh: '很少有学习者愿意放弃花了数月手写的笔记。', w: [592], note: '' },
  { id: 579, lv: 4, en: 'Resilient learners treat a low score as information, not as a verdict.', zh: '有韧性的学习者把低分当作信息，而不是判决。', w: [593], note: '' },
  { id: 580, lv: 4, en: 'The most salient point is that review must happen on the same day.', zh: '最突出的一点是：复习必须当天进行。', w: [594], note: '' },
  { id: 581, lv: 4, en: 'Take a moment to scrutinize the sentences where you lost the most points.', zh: '花点时间细看那些你丢分最多的句子。', w: [595], note: '' },
  { id: 582, lv: 4, en: 'A vocabulary that is never used slowly becomes stagnant and hard to recall.', zh: '从不使用的词汇会慢慢停滞，难以回想。', w: [596], note: '' },
  { id: 583, lv: 4, en: 'The rules stipulate that every member should read at least one book monthly.', zh: '规章规定每位成员每月至少读一本书。', w: [597], note: '' },
  { id: 584, lv: 4, en: 'New research can supersede advice that teachers repeated for many years.', zh: '新的研究可能取代老师们重复多年的建议。', w: [598], note: '' },
  { id: 585, lv: 4, en: 'The claim that grammar rules never change is simply not tenable.', zh: '语法规则永不变化这一说法根本站不住脚。', w: [599], note: '' },
  { id: 586, lv: 4, en: 'A vocabulary of about two thousand words is the threshold for real reading.', zh: '约两千词的词汇量是真正阅读的门槛。', w: [600], note: '' },
  { id: 587, lv: 4, en: 'Great books transcend the language they were first written in.', zh: '伟大的作品超越了它们最初被写就的语言。', w: [601], note: '' },
  { id: 588, lv: 4, en: 'A single short story can usher a shy student into a lifelong habit.', zh: '一篇短故事就能把一个害羞的学生引向终身习惯。', w: [602], note: '' },
  { id: 589, lv: 4, en: 'For most busy adults, twenty minutes a day is the only viable plan.', zh: '对多数忙碌的成年人来说，每天二十分钟是唯一可行的计划。', w: [603], note: '' },
  { id: 590, lv: 4, en: 'Be wary of any method that promises fluency within a single month.', zh: '对任何承诺一个月内流利的方法都要警惕。', w: [604], note: 'be wary of 警惕' },
  { id: 591, lv: 4, en: 'Her zeal for reading infected the whole class within just a few weeks.', zh: '她对阅读的热忱几周之内就感染了全班。', w: [605], note: '' },
  { id: 592, lv: 4, en: 'In the debate, his adversary spoke slowly and used very simple words.', zh: '辩论中，他的对手说得很慢，用词非常简单。', w: [606], note: '' },
  { id: 593, lv: 4, en: 'The aggregate number of words reviewed this term passed twenty thousand.', zh: '本学期累计复习的单词数超过两万。', w: [607], note: '' },
  { id: 594, lv: 4, en: 'Not making mistakes early can be benign only if you keep progressing.', zh: '只有在你持续进步时，早期不犯错才是无害的。', w: [608], note: '' },
  { id: 595, lv: 4, en: 'Bureaucracy slowed the new reading programme down by almost a whole year.', zh: '官僚流程把新阅读计划拖慢了将近一整年。', w: [609], note: '' },
  { id: 596, lv: 4, en: 'Smart learners capitalize on the ten minutes they wait for the bus.', zh: '聪明的学习者会利用等公交的十分钟。', w: [610], note: 'capitalize on 利用' },
  { id: 597, lv: 4, en: 'At the commencement of the course, everyone received a short word list.', zh: '课程开始时，每个人都拿到一份简短单词表。', w: [611], note: '' },
  { id: 598, lv: 4, en: 'The configuration of the app lets you hide words you already know.', zh: '这款应用的配置允许你隐藏已认识的词。', w: [612], note: '' },
  { id: 599, lv: 4, en: 'Her debut novel was short, simple and perfect for language learners.', zh: '她的处女作小说简短易懂，非常适合语言学习者。', w: [613], note: '' },
  { id: 600, lv: 4, en: 'The introduction delineates exactly which words this course will cover each week.', zh: '前言明确界定了本课程每周覆盖哪些单词。', w: [614], note: '' },
  { id: 601, lv: 4, en: 'Meaning in English is often diffuse, spreading across the whole sentence.', zh: '英语中的意义常常是扩散的，散布在整个句子里。', w: [615], note: '' },
  { id: 602, lv: 4, en: 'A discreet correction after class works better than one in front of everyone.', zh: '课后谨慎的纠正比当众纠正效果更好。', w: [616], note: '' },
  { id: 603, lv: 4, en: 'One good story can dispel the fear that reading in English is boring.', zh: '一个好故事能驱散"英语阅读很无聊"的恐惧。', w: [617], note: '' },
  { id: 604, lv: 4, en: 'The old teacher was a little eccentric, but his lessons were unforgettable.', zh: '那位老教师有点古怪，但他的课令人难忘。', w: [618], note: '' },
  { id: 605, lv: 4, en: 'Confidence in speaking seems to emanate from the words you truly own.', zh: '口语自信似乎源自你真正掌握的词。', w: [619], note: 'emanate from 源自' },
  { id: 606, lv: 4, en: 'Do not generalize from one difficult text to the whole English language.', zh: '不要从一篇难文章就推及整个英语语言。', w: [620], note: 'generalize from 从……概括' },
  { id: 607, lv: 4, en: 'Small weekly prizes are a harmless inducement for younger learners to read.', zh: '每周小奖品对年幼学习者是无害的激励。', w: [621], note: '' },
  { id: 608, lv: 4, en: 'Reading only one kind of text keeps a learner\'s vocabulary narrow and insular.', zh: '只读一类文本会让学习者的词汇狭窄封闭。', w: [622], note: '' },
  { id: 609, lv: 4, en: 'Good teachers interrogate a text instead of simply reading it aloud to students.', zh: '好老师会追问文本，而不只是朗读给学生听。', w: [623], note: '' },
  { id: 610, lv: 4, en: 'One bad experience does not negate months of quiet, steady progress.', zh: '一次糟糕的经历无法抹消数月平静稳定的进步。', w: [624], note: '' },
  { id: 611, lv: 4, en: 'There is a paradox: the more you read, the more new words you meet.', zh: '存在一个悖论：你读得越多，遇到的生词越多。', w: [625], note: '' },
  { id: 612, lv: 4, en: 'Poor teaching methods can perpetuate the fear of speaking for many years.', zh: '糟糕的教学方法会让对口语的恐惧延续多年。', w: [626], note: '' },
  { id: 613, lv: 4, en: 'Free word apps have proliferated far faster than good reading materials.', zh: '免费单词应用激增的速度远快于优质阅读材料。', w: [627], note: '' },
  { id: 614, lv: 4, en: 'A public rebuke rarely helps; a quiet word afterwards usually does.', zh: '当众斥责很少有用，事后私下说一句通常有用。', w: [628], note: '' },
  { id: 615, lv: 4, en: 'It is hard to reconcile the desire for speed with the need for review.', zh: '很难调和追求速度与需要复习之间的矛盾。', w: [629], note: 'reconcile A with B' },
  { id: 616, lv: 4, en: 'Half of the notes became redundant once the new word list arrived.', zh: '新单词表一到，一半笔记就成了多余的。', w: [630], note: '' },
  { id: 617, lv: 4, en: 'Let me reiterate the one rule that matters: review on the same day.', zh: '让我重申唯一重要的规则：当天复习。', w: [631], note: '' },
  { id: 618, lv: 4, en: 'The remuneration for part-time teaching here is modest but the students are wonderful.', zh: '这里兼职教学的报酬不高，但学生很棒。', w: [632], note: '' },
  { id: 619, lv: 4, en: 'Recent years have seen a resurgence of interest in reading paper books.', zh: '近年来人们对读纸质书的兴趣出现复苏。', w: [633], note: '' },
  { id: 620, lv: 4, en: 'Do not saturate your schedule with apps; leave time for real reading.', zh: '别让应用占满日程，要给真正的阅读留时间。', w: [634], note: '' },
  { id: 621, lv: 4, en: 'Moving to a new city can sever the reading habits you built for years.', zh: '搬到新城市可能切断你多年养成的阅读习惯。', w: [635], note: '' },
  { id: 622, lv: 4, en: 'Too many rules can stifle the simple joy of reading a story.', zh: '太多规则会扼杀读故事的简单乐趣。', w: [636], note: '' },
  { id: 623, lv: 4, en: 'Harsh testing can subvert a child\'s natural love of stories and words.', zh: '严苛的考试会破坏孩子对故事和词语天然的热爱。', w: [637], note: '' },
  { id: 624, lv: 4, en: 'With steady review you can surmount the barrier of the first thousand words.', zh: '通过稳定复习，你能越过最初一千词的障碍。', w: [638], note: '' },
  { id: 625, lv: 4, en: 'There is a tacit agreement in this class: nobody laughs at a mistake.', zh: '这个班有个心照不宣的约定：没人嘲笑错误。', w: [639], note: '' },
  { id: 626, lv: 4, en: 'Constant interruptions will undermine even the best-planned evening study session.', zh: '不断打断会破坏哪怕计划得最好的晚间学习。', w: [640], note: '' }
];

export { SENTENCES };
